    (function(){
      var btn = document.getElementById('btnAppBack');
      if (!btn) return;
      // Pile de navigation : on garde l'historique des pages visitées
      window._navStack = window._navStack || ['page-presentation'];

      function checkBack() {
        var pages = document.querySelectorAll('.page.active');
        var current = pages[0];
        if (!current) { btn.style.display = 'none'; return; }
        var id = current.id;
        // Toujours montrer le bouton SAUF sur la page de présentation (point d'entrée)
        if (id === 'page-presentation') {
          btn.style.display = 'none';
        } else {
          btn.style.display = 'inline-flex';
        }
      }

      window.appGoBack = function() {
        // Retour intelligent via la pile de navigation
        var stack = window._navStack || [];
        if (stack.length > 1) {
          // Retire la page courante, prend la précédente
          stack.pop();
          var prev = stack[stack.length - 1];
          if (typeof showPage === 'function' && prev) {
            // Empêcher l'ajout en double dans la pile lors du retour
            window._navInBack = true;
            showPage(prev);
            window._navInBack = false;
            return;
          }
        }
        // Fallback : retour à la page de présentation
        if (typeof showPage === 'function') {
          showPage('page-presentation');
        }
      };

      // Intercepter showPage pour empiler la navigation
      var origShowPage = window.showPage;
      if (typeof origShowPage === 'function') {
        window.showPage = function(id) {
          var r = origShowPage.apply(this, arguments);
          // Empiler dans la pile sauf si c'est un retour en cours
          if (!window._navInBack && id) {
            var stack = window._navStack || [];
            // Éviter doublons consécutifs
            if (stack[stack.length - 1] !== id) {
              stack.push(id);
              // Limiter à 50 entrées
              if (stack.length > 50) stack.shift();
              window._navStack = stack;
            }
          }
          setTimeout(checkBack, 50);
          return r;
        };
      }
      checkBack();
    })();
    
