// ── LOCALSTORAGE SÉCURISÉ — anti quota exceeded ──
function lsSet(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch(e) {
    // Quota dépassé — nettoyer SANS récursion
    try {
      // Vider tous les brouillons anciens
      var toDelete = [];
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (k && k.indexOf('haccp_brouillon_') === 0) toDelete.push(k);
      }
      toDelete.forEach(function(k){ try { localStorage.removeItem(k); } catch(x){} });
      // Vider l'historique
      try { localStorage.removeItem('haccp_historique'); } catch(x){}
      // Réessayer avec localStorage.setItem direct (pas de récursion)
      try {
        localStorage.setItem(key, value);
        return true;
      } catch(e2) {
        console.warn('localStorage quota dépassé — données non sauvegardées');
        if (typeof showToast === 'function') showToast('⚠️ Stockage plein — données non sauvegardées. Libérez de l\'espace.', 'err', 5000);
        return false;
      }
    } catch(e3) {
      console.warn('localStorage quota dépassé — données non sauvegardées');
      if (typeof showToast === 'function') showToast('⚠️ Stockage plein — données non sauvegardées. Libérez de l\'espace.', 'err', 5000);
      return false;
    }
  }
}

function lsGet(key) {
  try { return localStorage.getItem(key); } catch(e) { return null; }
}

function lsRemove(key) {
  try { localStorage.removeItem(key); } catch(e) {}
}

// V80 — Helpers de gestion du stockage (limite Safari ~5 Mo)
function estimerTailleStockage() {
  // Retourne {bytes, mo, pct, total_mo} — estimation du localStorage utilisé par HACCP Pro
  try {
    var total = 0;
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      var v = localStorage.getItem(k) || '';
      total += k.length + v.length;
    }
    var totalMo = total / (1024 * 1024);
    var limMo = 5; // limite typique Safari iOS
    return { bytes: total, mo: totalMo, pct: Math.min(100, totalMo / limMo * 100), total_mo: limMo };
  } catch(e) { return { bytes: 0, mo: 0, pct: 0, total_mo: 5 }; }
}

function nettoyerBrouillons() {
  if (!confirm('Voulez-vous vider tous les brouillons en cours ?\n\n(Vos PDF déjà téléchargés et historiques validés ne seront pas affectés.)')) return false;
  var nb = 0;
  try {
    var keys = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf('haccp_brouillon_') === 0) keys.push(k);
    }
    keys.forEach(function(k){ try { localStorage.removeItem(k); nb++; } catch(e){} });
    if (typeof showToast === 'function') showToast('✅ ' + nb + ' brouillon(s) supprimé(s)', 'ok', 3000);
  } catch(e) {
    if (typeof showToast === 'function') showToast('Erreur lors du nettoyage', 'err', 3000);
  }
  return nb;
}

// V80 — Rafraîchit l'indicateur visuel de stockage dans Réglages
function rafraichirIndicateurStockage() {
  var info = estimerTailleStockage();
  var moEl = document.getElementById('storage_mo');
  var barEl = document.getElementById('storage_bar');
  if (moEl) moEl.textContent = info.mo.toFixed(2);
  if (barEl) {
    barEl.style.width = info.pct + '%';
    if (info.pct > 80) barEl.style.background = 'linear-gradient(90deg,#dc2626,#ef4444)';
    else if (info.pct > 60) barEl.style.background = 'linear-gradient(90deg,#f59e0b,#fbbf24)';
    else barEl.style.background = 'linear-gradient(90deg,#10b981,#16a34a)';
  }
}

// ── HELPERS SESSION avec FALLBACK sessionStorage (Safari iOS, mode privé) ──
// Écrit en parallèle dans localStorage (persistant) ET sessionStorage (fallback onglet)
// Lit en priorité localStorage, sinon sessionStorage
var SESSION_KEY = 'haccp_session_v10';
function sessionWrite(value) {
  try { localStorage.setItem(SESSION_KEY, value); } catch(e) {}
  try { sessionStorage.setItem(SESSION_KEY, value); } catch(e) {}
}
function sessionRead() {
  try {
    var v = localStorage.getItem(SESSION_KEY);
    if (v) return v;
  } catch(e) {}
  try {
    var v2 = sessionStorage.getItem(SESSION_KEY);
    if (v2) {
      // localStorage vide mais sessionStorage présent → tenter de restaurer localStorage
      try { localStorage.setItem(SESSION_KEY, v2); } catch(x){}
      return v2;
    }
  } catch(e) {}
  return null;
}
function sessionClear() {
  try { localStorage.removeItem(SESSION_KEY); } catch(e) {}
  try { sessionStorage.removeItem(SESSION_KEY); } catch(e) {}
}

// ── TOAST NOTIFICATIONS (remplace alert) ──
var _toastTimer = null;
function showToast(msg, type, duration) {
  var el = document.getElementById('toastNotif');
  if (!el) return;
  el.textContent = msg;
  el.className = 'toast-notif show' + (type ? ' toast-' + type : '');
  if (_toastTimer) clearTimeout(_toastTimer);
  _toastTimer = setTimeout(function(){ el.classList.remove('show'); }, duration || 3000);
}

// ── INDICATEUR DE CHARGEMENT (opérations longues) ──
// showLoader : overlay bloquant pour login, sauvegardes manuelles
// hideLoader : ferme l'overlay
// pulseSync  : indicateur discret pour sync silencieuse (Supabase background)
function showLoader(msg) {
  var ov = document.getElementById('haccpLoaderOverlay');
  var ms = document.getElementById('haccpLoaderMsg');
  if (!ov) return;
  if (ms) ms.textContent = msg || 'Chargement…';
  ov.classList.add('show');
}
function hideLoader() {
  var ov = document.getElementById('haccpLoaderOverlay');
  if (ov) ov.classList.remove('show');
}
var _syncTimer = null;
function pulseSync(msg) {
  var el = document.getElementById('haccpSyncPulse');
  if (!el) return;
  el.textContent = msg || 'Synchronisation…';
  el.classList.add('show');
  if (_syncTimer) clearTimeout(_syncTimer);
  _syncTimer = setTimeout(function(){ el.classList.remove('show'); }, 1200);
}

// ── ACCESSIBILITÉ : auto-aria-label sur boutons icône seule ──
// Parcourt les <button> sans aria-label dont le contenu textuel est très court (emoji uniquement)
// et leur attribue un aria-label déduit du contexte (className, onclick, title)
var ICON_LABELS = {
  '✕': 'Fermer',
  '×': 'Fermer',
  '✖': 'Fermer',
  '🗑': 'Supprimer',
  '🔄': 'Actualiser',
  '➕': 'Ajouter',
  '➖': 'Retirer',
  '✅': 'Valider',
  '❌': 'Annuler',
  '←': 'Retour',
  '→': 'Suivant',
  '↑': 'Monter',
  '↓': 'Descendre',
  '📷': 'Prendre une photo',
  '📸': 'Prendre une photo',
  '📁': 'Choisir un fichier',
  '✏️': 'Modifier',
  '👁': 'Voir',
  '👁️': 'Voir',
};
function autoAriaLabels() {
  try {
    var btns = document.querySelectorAll('button:not([aria-label]), [role="button"]:not([aria-label])');
    btns.forEach(function(b){
      var txt = (b.textContent||'').trim();
      // Bouton icône seule (très court, sans lettres)
      if (txt.length <= 5 && !/[a-zA-Z]/.test(txt)){
        // Priorité 1 : title attribut existant
        var tt = b.getAttribute('title');
        if (tt && tt.length > 1) { b.setAttribute('aria-label', tt); return; }
        // Priorité 2 : classe btn-delete → Supprimer
        var cls = b.className || '';
        if (typeof cls === 'string' && cls.indexOf('btn-delete') !== -1) { b.setAttribute('aria-label', 'Supprimer'); return; }
        // Priorité 3 : map d'icônes
        for (var icon in ICON_LABELS){
          if (txt.indexOf(icon) !== -1) { b.setAttribute('aria-label', ICON_LABELS[icon]); return; }
        }
      }
    });
  } catch(e) {}
}
// Lancer une fois au chargement complet
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', autoAriaLabels);
} else {
  setTimeout(autoAriaLabels, 100);
}

// ── CAPTEUR D'ERREURS GLOBAL (debug mobile) ──
// Affiche les erreurs JS dans la zone login_error pour pouvoir les voir sans DevTools
window.addEventListener('error', function(ev) {
  try {
    if (typeof hideLoader === 'function') hideLoader();
    var btn = document.getElementById('login_btn');
    if (btn) { btn.textContent = '🔑 Se connecter'; btn.disabled = false; }
    var errEl = document.getElementById('login_error');
    if (errEl) {
      var src = ev.filename ? (ev.filename.split('/').pop() + ':' + (ev.lineno||'?')) : '?';
      var emsg = ev.message || 'Erreur inconnue';
      errEl.textContent = '⚠️ ' + emsg + ' (' + src + ')';
      errEl.style.display = 'block';
    }
  } catch(e) {}
});
window.addEventListener('unhandledrejection', function(ev) {
  try {
    if (typeof hideLoader === 'function') hideLoader();
    var btn = document.getElementById('login_btn');
    if (btn) { btn.textContent = '🔑 Se connecter'; btn.disabled = false; }
    var errEl = document.getElementById('login_error');
    if (errEl) {
      var r = ev.reason;
      var emsg = (r && r.message) ? r.message : (typeof r === 'string' ? r : JSON.stringify(r));
      errEl.textContent = '⚠️ Promise rejetée : ' + emsg;
      errEl.style.display = 'block';
    }
  } catch(e) {}
});

// ── CONFIRM MODAL (remplace confirm()) ──
var _confirmCb = null;
function showConfirm(ico, title, msg, okLabel, okClass, callback) {
  document.getElementById('confirmIco').textContent = ico || '⚠️';
  document.getElementById('confirmTitle').textContent = title || 'Confirmation';
  document.getElementById('confirmMsg').textContent = msg || '';
  var okBtn = document.getElementById('confirmOk');
  okBtn.textContent = okLabel || 'Continuer';
  okBtn.className = 'confirm-btn-ok' + (okClass ? ' ' + okClass : '');
  document.getElementById('confirmOverlay').classList.add('show');
  _confirmCb = callback;
}
document.addEventListener('DOMContentLoaded', function() {
  var okBtn = document.getElementById('confirmOk');
  var cancelBtn = document.getElementById('confirmCancel');
  if (okBtn) okBtn.addEventListener('click', function() {
    document.getElementById('confirmOverlay').classList.remove('show');
    if (_confirmCb) { _confirmCb(true); _confirmCb = null; }
  });
  if (cancelBtn) cancelBtn.addEventListener('click', function() {
    document.getElementById('confirmOverlay').classList.remove('show');
    if (_confirmCb) { _confirmCb(false); _confirmCb = null; }
  });
  // V54 — restaurer le mode "champs facultatifs visibles" si activé précédemment
  if (typeof initAdvancedMode === 'function') initAdvancedMode();
  // V80 — Injecter le bandeau de responsabilité avant chaque bouton "Valider"
  if (typeof injecterAvertissementResponsabilite === 'function') injecterAvertissementResponsabilite();
  // V80 — Marquer automatiquement les champs facultatifs (sans ★) pour qu'ils soient masquables
  if (typeof marquerChampsFacultatifsAuto === 'function') marquerChampsFacultatifsAuto();
  // V80 — Observer le DOM pour marquer les champs facultatifs ajoutés dynamiquement (via ajouterPlat, ajouterProduit, etc.)
  try {
    var obsAdv = new MutationObserver(function(mutations) {
      var found = false;
      mutations.forEach(function(m) {
        if (m.addedNodes && m.addedNodes.length) {
          m.addedNodes.forEach(function(n) {
            if (n.nodeType === 1 && n.querySelector && (n.querySelector('.frow') || n.classList.contains('frow') || n.querySelector('.fblock'))) {
              found = true;
            }
          });
        }
      });
      if (found && typeof marquerChampsFacultatifsAuto === 'function') {
        // Petite latence pour laisser le DOM se stabiliser après un appendChild
        setTimeout(marquerChampsFacultatifsAuto, 50);
      }
    });
    obsAdv.observe(document.body, {childList: true, subtree: true});
  } catch(e) {}
  // V80 — Activer l'autocomplete sur tous les inputs marqués data-loc-auto + observer le DOM pour les nouveaux
  function attachAllLocInputs() {
    document.querySelectorAll('input[data-loc-auto="1"]').forEach(function(inp){
      if (typeof attachAutocompleteLocalisation === 'function') attachAutocompleteLocalisation(inp);
    });
  }
  attachAllLocInputs();
  // Observer les ajouts dynamiques (modules qui créent des inputs au runtime)
  try {
    var obs = new MutationObserver(function(mutations) {
      var found = false;
      mutations.forEach(function(m) {
        if (m.addedNodes && m.addedNodes.length) {
          m.addedNodes.forEach(function(n) {
            if (n.nodeType === 1 && (n.matches && n.matches('input[data-loc-auto="1"]') || n.querySelector && n.querySelector('input[data-loc-auto="1"]'))) {
              found = true;
            }
          });
        }
      });
      if (found) attachAllLocInputs();
    });
    obs.observe(document.body, {childList: true, subtree: true});
  } catch(e) {}
});

// V80 — Bandeau permanent rappelant la responsabilité du restaurateur
// Règle de validation : seul blocage = signature + nom + prénom. Le reste relève de la responsabilité du client.
// Le bandeau est placé EN HAUT de chaque page module (visible dès l'ouverture).
function injecterAvertissementResponsabilite() {
  // V80 — Insère le bandeau pédagogique JUSTE AU-DESSUS de chaque bouton "Valider"
  // (et non en haut de page, pour qu'il soit visible au moment de valider)
  var pagesModules = ['page-reception','page-temperatures','page-hygiene','page-ouverture',
    'page-cuisson','page-refroidissement','page-huiles','page-etiquetage','page-fermeture',
    'page-pertes','page-dechets','page-nuisibles','page-documents','page-affichage',
    'page-nc','page-audits','page-plat-temoin','page-liaison-thermique',
    'page-registre-convives','page-analyses-micro','page-allergenes'];
  pagesModules.forEach(function(pageId) {
    var page = document.getElementById(pageId);
    if (!page) return;
    // Retirer un éventuel bandeau existant en haut de page (anciennement)
    var oldBandeau = page.querySelector('.bandeau-responsabilite');
    while (oldBandeau) {
      oldBandeau.remove();
      oldBandeau = page.querySelector('.bandeau-responsabilite');
    }
    // Trouver les boutons "Valider" / "Enregistrer" dans cette page
    var validerBtns = page.querySelectorAll('button.btn-p[onclick*="valider"], button.btn-p[onclick*="enregistrer"], button.btn-p[onclick*="Valider"]');
    validerBtns.forEach(function(btn) {
      // Si un bandeau existe déjà juste avant ce bouton, ne rien faire
      var prev = btn.previousElementSibling;
      if (prev && prev.classList && prev.classList.contains('bandeau-responsabilite')) return;
      var b = document.createElement('div');
      b.className = 'bandeau-responsabilite';
      b.style.cssText = 'background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:12px 14px;margin:14px 14px 8px;color:#78350f;font-size:11.5px;line-height:1.55';
      b.innerHTML =
        '<div style="display:flex;align-items:center;gap:8px;font-weight:800;font-size:12.5px;color:#92400e;margin-bottom:6px">' +
          '<span style="font-size:14px">⚠️</span>Avant de valider' +
        '</div>' +
        '<div style="margin-bottom:8px">Les cases marquées d\'un astérisque rouge <strong style="color:#dc2626">★</strong> doivent être renseignées. À défaut, le rapport sera considéré comme <strong>non conforme</strong> et pourra être rejeté lors d\'un contrôle DDPP.</div>' +
        '<div style="font-size:11px;color:#92400e;font-style:italic;margin-bottom:8px">Validation sous votre seule responsabilité, conformément à votre Plan de Maîtrise Sanitaire (Règlement CE 852/2004).</div>' +
        '<button type="button" class="btn-toggle-adv" data-adv-label="facultatifs" onclick="toggleAdvanced()" style="background:#fef3c7;border:1px solid #fde68a;color:#92400e;font-size:11px;font-weight:700;padding:6px 12px;border-radius:8px;cursor:pointer;font-family:Outfit,sans-serif">⚙️ Afficher champs facultatifs</button>';
      btn.parentNode.insertBefore(b, btn);
    });
  });
  // V80 — Synchroniser tous les boutons toggle avec l'état actuel
  if (typeof _advancedVisible !== 'undefined') {
    document.querySelectorAll('.btn-toggle-adv').forEach(function(b) {
      var labelType = b.dataset.advLabel || 'facultatifs';
      b.textContent = (_advancedVisible ? '⚙️ Masquer champs ' : '⚙️ Afficher champs ') + labelType;
    });
  }
}

