var ETAB = {
  secteur: '', nom: '', adresse: '', cp: '', ville: '',
  tel: '', email: '', siret: '', responsable: '', fonction: '',
  // Restauration
  couverts: '', services: '', typeCuisine: '',
  // Boulangerie
  surface: '', fournils: '', vente: '',
  // Restauration rapide
  postes: '', volumeJour: '', mode: '',
  // Boucherie
  typeActivite: '', agrement: '',
  // Collective
  typeStructure: '', repasJour: '', liaison: '',
};

try {
  var _etabStored = lsGet('haccp_etab');
  if (_etabStored) ETAB = JSON.parse(_etabStored);
  var _etabId = lsGet('haccp_etab_id');
  if (_etabId) ETAB_ID = _etabId;
} catch(e) {}

// ── CONNEXION ──
async function connexion() {
  var code = (document.getElementById('login_code').value || '').trim().toUpperCase();
  var pwd = (document.getElementById('login_pwd').value || '').trim();
  var errEl = document.getElementById('login_error');
  var btn = document.getElementById('login_btn');
  if (!code) { errEl.textContent = 'Saisissez votre code d\'accès.'; errEl.style.display='block'; return; }
  if (!pwd) { errEl.textContent = 'Saisissez votre mot de passe.'; errEl.style.display='block'; return; }
  errEl.style.display = 'none';
  btn.textContent = '⏳ Connexion en cours...'; btn.disabled = true;
  if (typeof showLoader === 'function') showLoader('Connexion à votre établissement…');
  var result;
  try {
    result = await sbLogin(code, pwd);
  } catch(err) {
    var emsg = (err && err.message) ? err.message : String(err);
    console.error('connexion() exception:', emsg);
    result = { ok: false, msg: 'Erreur de connexion : ' + emsg };
  } finally {
    if (typeof hideLoader === 'function') hideLoader();
    btn.textContent = '🔑 Se connecter'; btn.disabled = false;
  }
  if (!result || !result.ok) {
    errEl.textContent = (result && result.msg) ? result.msg : 'Erreur inconnue.'; errEl.style.display = 'block'; return;
  }
  // Connexion réussie
  var d = result.data;
  // V105 — Mémoriser le code d'accès pour la prochaine session (pas le mot de passe)
  try { lsSet('haccp_last_code', code); } catch(e) {}
  ETAB_ID = d.id;
  SECTEUR_ACTIF = d.secteur || 'resto';
  ETAB.nom = d.nom || '';
  ETAB.siret = d.siret || '';
  ETAB.adresse = d.adresse || '';
  ETAB.secteur = d.secteur || 'resto';
  try {
    lsSet('haccp_etab', JSON.stringify(ETAB));
    lsSet('haccp_etab_id', ETAB_ID);
    // Session 24h
    sessionWrite(JSON.stringify({
      etabId: ETAB_ID,
      etabNom: d.nom,
      secteur: d.secteur || 'resto',
      siret: d.siret || '',
      adresse: d.adresse || '',
      loginAt: Date.now(),
      pwdOk: true,
    }));
  } catch(e) {}
  SB_READY = true;
  // V102 — Mettre à jour le bandeau du haut avec les vraies infos client
  try { if (typeof updateTopbarEtab === 'function') updateTopbarEtab(); } catch(e){}
  // Indicateur mode local — V106 : bandeau retiré côté client (visible uniquement en console)
  if (MODE_LOCAL) {
    console.info('[V106] Mode local actif — connexion via CODES_LOCAUX (bandeau client supprimé)');
  }
  // V80 — Login → écran de choix du secteur (étape 1 uniquement, pas la fiche).
  // Le secteur en base est utilisé comme défaut, mais l'utilisateur peut en changer (msg #88).
  // choisirSecteur() bypass ensuite l'étape 2 (fiche) pour aller direct à page-choix (mode guidé/expert).
  INGREDIENTS_DB = SECTEUR_ACTIF === 'bp' ? INGREDIENTS_BP : INGREDIENTS_RESTO;
  var heroEl = document.getElementById('heroEtab'); if (heroEl) heroEl.textContent = ETAB.nom;
  var nomEl = document.getElementById('onb_nom');
  if (nomEl && d.nom) nomEl.value = d.nom;
  document.getElementById('onb_back_btn').style.display = 'none';
  document.getElementById('onb_step1').style.display = 'block';
  document.getElementById('onb_step2').style.display = 'none';
  // V80 — CLIENT_MODE désactivé par défaut pour permettre à l'admin/testeur
  // de voir tous les secteurs (msg #80 : "parfois je veux changer").
  // V101 — Réactivé automatiquement pour les vrais clients commerciaux (codes HACCP-XXXXX-YYYY)
  var codeUpper = (d.code_acces || '').toUpperCase();
  if (codeUpper.indexOf('HACCP-') === 0) {
    CLIENT_MODE = true;
    console.log('[V101] CLIENT_MODE activé pour code commercial:', codeUpper);
  } else {
    CLIENT_MODE = false;
  }
  // V101 — Appliquer le grisage immédiatement après l'affichage du choix secteur
  setTimeout(appliquerClientMode, 50);
  var sa=document.getElementById('scrollArea'); if(sa) sa.scrollTop=0; window.scrollTo(0,0);
  showPage('page-onboarding');
}

// V80 — Masque les boutons secteurs autres que celui du client connecté
// V101 — Modifié : grise les autres secteurs au lieu de les cacher, avec popup au clic
function appliquerClientMode() {
  if (!CLIENT_MODE || !ETAB.secteur) return;
  var secteurClient = ETAB.secteur;
  var btns = document.querySelectorAll('#onb_step1 .onb-secteur-btn');
  btns.forEach(function(btn) {
    var onclick = btn.getAttribute('onclick') || '';
    var m = onclick.match(/choisirSecteur\('(\w+)'\)/);
    if (m) {
      var secteurBtn = m[1];
      if (secteurBtn === secteurClient) {
        // Secteur autorisé : mise en valeur
        btn.style.opacity = '1';
        btn.style.border = '2px solid #4ade80';
        btn.style.boxShadow = '0 0 0 3px rgba(74,222,128,0.15)';
        // Ajouter badge "MON SECTEUR" si pas déjà
        if (!btn.querySelector('.badge-mon-secteur')) {
          var badge = document.createElement('div');
          badge.className = 'badge-mon-secteur';
          badge.style.cssText = 'position:absolute;top:8px;right:8px;background:linear-gradient(135deg,#4ade80,#22c55e);color:#0a0e1a;font-size:9px;font-weight:900;padding:3px 8px;border-radius:10px;letter-spacing:0.5px';
          badge.textContent = '✓ MON SECTEUR';
          btn.style.position = 'relative';
          btn.appendChild(badge);
        }
      } else {
        // Secteur non autorisé : grisé + cadenas
        btn.style.opacity = '0.4';
        btn.style.cursor = 'not-allowed';
        btn.style.filter = 'grayscale(80%)';
        // Remplacer l'onclick par la popup
        btn.setAttribute('onclick', "secteurVerrouille('" + secteurBtn + "'); return false;");
        // Ajouter cadenas si pas déjà
        if (!btn.querySelector('.cadenas-lock')) {
          var lock = document.createElement('div');
          lock.className = 'cadenas-lock';
          lock.style.cssText = 'position:absolute;top:8px;right:8px;font-size:18px';
          lock.textContent = '🔒';
          btn.style.position = 'relative';
          btn.appendChild(lock);
        }
      }
    }
  });
  // Masquer le bouton modeTest aussi (réservé au testeur, pas au client)
  var modeBtn = document.querySelector('#onb_step1 button[onclick*="modeTest"]');
  if (modeBtn) modeBtn.style.display = 'none';
}

