// ══════════════════════════════════════════════════════════
// RESET COMPLET D'UN MODULE — appelé à chaque ouverture
// Remet tous les champs, statuts, signatures, blocs dyna à zéro
// ══════════════════════════════════════════════════════════
var MODULE_PAGES = ['page-reception', 'page-temperatures', 'page-hygiene', 'page-ouverture', 'page-cuisson', 'page-refroidissement', 'page-huiles', 'page-etiquetage', 'page-fermeture', 'page-pertes', 'page-dechets', 'page-nuisibles', 'page-documents', 'page-affichage', 'page-nc', 'page-audits'];


function initHeuresAuto(pageId) {
  var page = document.getElementById(pageId);
  if (!page) return;
  var now = new Date();
  var hh = String(now.getHours()).padStart(2,'0');
  var mm = String(now.getMinutes()).padStart(2,'0');
  var heureNow = hh + ':' + mm;
  page.querySelectorAll('input[type=time]').forEach(function(el) {
    if (!el.value) el.value = heureNow;
  });
}
function resetModule(pageId) {
  var page = document.getElementById(pageId);
  if (!page) return;

  // 1. Vider tous les champs texte/date/number/time/textarea
  page.querySelectorAll('input[type=text], input[type=date], input[type=number], input[type=time], input[type=email], input[type=tel], textarea').forEach(function(el) {
    // Ne pas effacer les champs système (timestamp auto, etc.)
    if (el.id && el.id.includes('timestamp')) return;
    el.value = '';
  });

  // 2. Remettre tous les selects à l'index 0
  page.querySelectorAll('select').forEach(function(el) {
    el.selectedIndex = 0;
  });

  // 3. Retirer tous les statuts actifs (ok/warn/bad)
  page.querySelectorAll('.status-btn').forEach(function(btn) {
    btn.classList.remove('active-ok', 'active-warn', 'active-bad');
  });

  // 4. Masquer toutes les NC auto
  page.querySelectorAll('.nc-auto').forEach(function(el) {
    el.style.display = 'none';
  });

  // 5. Masquer toutes les actions correctives
  page.querySelectorAll('.nc-action').forEach(function(el) {
    el.classList.remove('visible');
  });

  // 6. Supprimer les blocs d'action corrective créés dynamiquement
  page.querySelectorAll('[data-generic="1"]').forEach(function(el) {
    el.remove();
  });
  page.querySelectorAll('[id^="emb_abime_action_"]').forEach(function(el) {
    el.remove();
  });

  // 7. Masquer les blocs conditionnels
  page.querySelectorAll('.obs-hidden').forEach(function(el) {
    el.classList.remove('visible');
  });
  page.querySelectorAll('[id="gastroZone"]').forEach(function(el) {
    el.style.display = 'none';
  });

  // 8. Réinitialiser les badges de conformité
  page.querySelectorAll('.conformite-badge').forEach(function(el) {
    el.className = 'conformite-badge pending';
    el.textContent = 'Saisissez la temperature';
  });

  // 9. Effacer les signatures (canvas)
  page.querySelectorAll('canvas').forEach(function(canvas) {
    var ctx = canvas.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
  });
  // Réinitialiser les flags de signature
  var pageBase = pageId.replace('page-', '');
  // Reset flags de signature (noms des variables globales)
  var sigFlagMap = {
    'reception':       ['hasSig','isDrawing'],
    'temperatures':    ['hasSigTemp','isDrawingTemp'],
    'hygiene':         ['hasSigHyg','isDrawingHyg'],
    'ouverture':       ['hasSigOuv','isDrawingOuv'],
    'cuisson':         ['hasSigCuis','isDrawingCuis'],
    'refroidissement': ['hasSigRefroi','isDrawingRefroi'],
    'huiles':          ['hasSigHuile','isDrawingHuile'],
    'etiquetage':      ['hasSigEtiq','isDrawingEtiq'],
    'fermeture':       ['hasSigFerm','isDrawingFerm'],
    'pertes':          ['hasSigPertes','isDrawingPertes'],
    'dechets':         ['hasSigDechets','isDrawingDechets'],
    'nuisibles':       ['hasSigNuis','isDrawingNuis'],
    'documents':       ['hasSigDocs','isDrawingDocs'],
    'affichage':       ['hasSigAff','isDrawingAff'],
    'nc':              ['hasSigNC','isDrawingNC'],
    'audits':          ['hasSigAudit','isDrawingAudit'],
  };
  // Reset direct des flags hasSig* selon la page
  var sigResetMap = {
    'reception':['hasSig','isDrawing'],'temperatures':['hasSigTemp','isDrawingTemp'],
    'hygiene':['hasSigHyg','isDrawingHyg'],'ouverture':['hasSigOuv','isDrawingOuv'],
    'cuisson':['hasSigCuis','isDrawingCuis'],'refroidissement':['hasSigRefroi','isDrawingRefroi'],
    'huiles':['hasSigHuile','isDrawingHuile'],'etiquetage':['hasSigEtiq','isDrawingEtiq'],
    'fermeture':['hasSigFerm','isDrawingFerm'],'pertes':['hasSigPertes','isDrawingPertes'],
    'dechets':['hasSigDechets','isDrawingDechets'],'nuisibles':['hasSigNuis','isDrawingNuis'],
    'documents':['hasSigDocs','isDrawingDocs'],'affichage':['hasSigAff','isDrawingAff'],
    'nc':['hasSigNC','isDrawingNC'],'audits':['hasSigAudit','isDrawingAudit'],
  };
  try {
    switch(pageBase) {
      case 'reception': hasSig=false; isDrawing=false; break;
      case 'temperatures': hasSigTemp=false; isDrawingTemp=false; break;
      case 'hygiene': hasSigHyg=false; isDrawingHyg=false; break;
      case 'ouverture': hasSigOuv=false; isDrawingOuv=false; break;
      case 'cuisson': hasSigCuis=false; isDrawingCuis=false; break;
      case 'refroidissement': hasSigRefroi=false; isDrawingRefroi=false; break;
      case 'huiles': hasSigHuile=false; isDrawingHuile=false; break;
      case 'etiquetage': hasSigEtiq=false; isDrawingEtiq=false; break;
      case 'fermeture': hasSigFerm=false; isDrawingFerm=false; break;
      case 'pertes': hasSigPertes=false; isDrawingPertes=false; break;
      case 'dechets': hasSigDechets=false; isDrawingDechets=false; break;
      case 'nuisibles': hasSigNuis=false; isDrawingNuis=false; break;
      case 'documents': hasSigDocs=false; isDrawingDocs=false; break;
      case 'affichage': hasSigAff=false; isDrawingAff=false; break;
      case 'nc': hasSigNC=false; isDrawingNC=false; break;
      case 'audits': hasSigAudit=false; isDrawingAudit=false; break;
    }
  } catch(e) {}

  // 10. Supprimer les blocs produits/plats/friteuses/etc. créés dynamiquement
  var dynamicContainers = [
    'produitsContainer', 'enceintesDynamiquesContainer', 'enceintesPreconfigContainer',
    'cuisPlatContainer', 'platsTemoinsContainer',
    'refroiContainer', 'huileContainer', 'etiqContainer',
    'pertesContainer', 'dechetsContainer', 'ncContainer',
    'salariesList', 'allergContainer',
  ];
  dynamicContainers.forEach(function(cid) {
    var cont = document.getElementById(cid);
    if (cont) cont.innerHTML = '';
  });

  // 11. Réinitialiser compteurs dynamiques
  if (pageId === 'page-reception') { produitCount = 0; }
  if (pageId === 'page-temperatures')    { enceintesDynamiques = 0; }
  if (pageId === 'page-cuisson')         { try { platCount = 0; platTemoinCount = 0; } catch(e) {} }
  if (pageId === 'page-refroidissement') { try { refroiCount = 0; } catch(e) {} }
  if (pageId === 'page-huiles')          { try { friteusCount = 0; } catch(e) {} }
  if (pageId === 'page-etiquetage')      { try { etiqCount = 0; } catch(e) {} }
  if (pageId === 'page-pertes')          { try { pertesCount = 0; } catch(e) {} }
  if (pageId === 'page-dechets')         { try { dechetCount = 0; } catch(e) {} }
  if (pageId === 'page-nc')              { try { ncCount = 0; } catch(e) {} }
  if (pageId === 'page-reception')       { try { tracaCount = 0; } catch(e) {} }
  if (pageId === 'page-hygiene')         { try { salariesCount = 0; } catch(e) {} }

  // 12. Masquer les messages d'erreur et required
  page.querySelectorAll('.sig-required, [id$="_required"], [id$="_sig_required"]').forEach(function(el) {
    el.style.display = 'none';
  });
  // 12b.  d'erreur/required
  page.querySelectorAll('.sig-required, .nc-required, [id$="_required"]').forEach(function(el) {
    el.style.display = 'none';
  });

  // 13. Remettre le timestamp automatique si présent
  var tsEl = page.querySelector('[id$="_timestamp"]');
  if (tsEl) tsEl.value = getNowStr ? getNowStr() : '';
}

function showPage(id, noReset) {
  document.querySelectorAll('.page').forEach(function(p) { p.classList.remove('active'); });
  var target = document.getElementById(id);
  if (target) {
    target.classList.add('active');
    target.scrollTop = 0;
  }
  // V80 — Injecter/rafraîchir le bandeau de responsabilité dans le module si applicable
  if (typeof injecterAvertissementResponsabilite === 'function') {
    setTimeout(injecterAvertissementResponsabilite, 50);
  }
  // V80 — Marquer les champs facultatifs (au cas où des champs dynamiques aient été ajoutés)
  if (typeof marquerChampsFacultatifsAuto === 'function') {
    setTimeout(marquerChampsFacultatifsAuto, 100);
  }
  var sa = document.getElementById('scrollArea');
  if (sa) sa.scrollTop = 0;
  if (target) target.scrollIntoView({block:'start', behavior:'instant'});
  requestAnimationFrame(function() {
    if (sa) sa.scrollTop = 0;
    if (target) target.scrollTop = 0;
  });
  // Navigation historique — retour navigateur
  if (window.history && window.history.pushState) {
    window.history.pushState({page: id}, '', '');
  }
  // Modules gérés par ouvrirModule() — ont leur propre reset+init, ne pas double-resetter
  var geresParOuvrir = ['page-reception','page-temperatures','page-hygiene','page-ouverture',
    'page-cuisson','page-refroidissement','page-huiles','page-etiquetage','page-fermeture',
    'page-pertes','page-dechets','page-nuisibles','page-documents','page-affichage',
    'page-nc','page-audits'];
  var estGere = geresParOuvrir.indexOf(id) > -1;
  // V113 — B/C : si module fraîchement validé, forcer reset + purge brouillon AVANT la restauration
  if (typeof window !== 'undefined' && window._modulesValidatedFlag && window._modulesValidatedFlag[id]) {
    if (typeof resetModule === 'function') resetModule(id);
    if (typeof effacerBrouillon === 'function') effacerBrouillon(id);
    delete window._modulesValidatedFlag[id];
  }
  if (!noReset && MODULE_PAGES && MODULE_PAGES.indexOf(id) > -1) {
    if (!estGere) {
      resetModule(id);
    }
    setTimeout(function() {
      var tsEls = document.querySelectorAll('#' + id + ' [id$="_timestamp"], #' + id + ' .auto-timestamp');
      tsEls.forEach(function(el) { if (getNowStr) el.value = getNowStr(); });
      initHeuresAuto(id);
      afficherBandeauDerniereSession(id);
      if (id === 'page-nc') setTimeout(alimenterRegistreNC, 300);
      if (id === 'page-dashboard') setTimeout(initDashboard, 300);
      startBrouillonAuto(id);
      setTimeout(function(){ restaurerBrouillon(id); }, 200);
    }, 100);
  }
  // Accessibilité : ajouter aria-label sur boutons icône générés dynamiquement
  if (typeof autoAriaLabels === 'function') setTimeout(autoAriaLabels, 200);
}


function goHome() {
  showPage('page-guide');
  // Rafraîchir la grille des modules avec la catégorie active
  var activeCat = document.querySelector('.ctab.active');
  if (activeCat) {
    var cat = activeCat.getAttribute('data-cat') || currentCat || 'quotidien';
    renderMods(cat);
  } else {
    renderMods(currentCat || 'quotidien');
  }
  // Mettre à jour la nav
  document.querySelectorAll('.nitem').forEach(function(n){ n.classList.remove('active'); });
  var navHome = document.getElementById('nav-home');
  if (navHome) navHome.classList.add('active');
}
function navTo(key) {
  document.querySelectorAll('.nitem').forEach(function(n) { n.classList.remove('active'); });
  document.getElementById('nav-' + key).classList.add('active');
  var map = {home:'page-guide', history:'page-history', reports:'page-reports', settings:'page-settings'};
  showPage(map[key] || 'page-guide');
  if (key === 'history') chargerHistorique();
  if (key === 'settings') {
    chargerReglages();
    // V80 — Rafraîchir l'indicateur de stockage
    setTimeout(function(){ if (typeof rafraichirIndicateurStockage === 'function') rafraichirIndicateurStockage(); }, 100);
  }
}

