function updateEnceinteRef_check() {
  // Called from enceinte ref dropdowns — find parent block
  var el = event && event.target;
  if (!el) return;
  var block = el.closest('[id^="enc_block_"]');
  if (!block) return;
  var id = block.id.replace('enc_block_', '');
  updateEnceinteRef(id);
}
function updateEnceinteRef(id) {
  var typeEl = document.getElementById('enc_ref_type_' + id);
  var numEl = document.getElementById('enc_ref_num_' + id);
  var titleEl = document.querySelector('#enc_block_' + id + ' .fblock-title span');
  if (!titleEl) return;
  var cfg = SEUILS_ENCEINTE[typeEnceinteCourant] || {ico:'🌡️'};
  var typeTxt = typeEl && typeEl.value ? typeEl.value : '';
  var numTxt = numEl && numEl.value ? ' — ' + numEl.value : '';
  // Keep original icon + update label
  var origText = titleEl.textContent;
  var icoMatch = origText.match(/^(\S+)/); var ico = icoMatch ? icoMatch[1] : '🌡️';
  if (typeTxt) titleEl.textContent = ico + ' ' + typeTxt + numTxt;
  else if (numTxt) titleEl.textContent = origText.split(' — ')[0] + numTxt;
}

function buildEnceinteOptions() {
  var secteur = (typeof SECTEUR_ACTIF !== 'undefined' && SECTEUR_ACTIF) ? SECTEUR_ACTIF : 'resto';
  var base = (TYPES_ENCEINTES && TYPES_ENCEINTES.base) ? TYPES_ENCEINTES.base : [];
  var spec = (TYPES_ENCEINTES && TYPES_ENCEINTES[secteur]) ? TYPES_ENCEINTES[secteur] : [];
  var valsBase = base.map(function(t){ return t.val; });
  var specFiltered = spec.filter(function(t){ return valsBase.indexOf(t.val) === -1; });
  var html = '<option value="">— Selectionner le type —</option>';
  base.forEach(function(t) {
    var s = t.seuil !== null ? ' (<=' + (t.seuil < 0 ? '' : '+') + t.seuil + 'C)' : ' (Manuel)';
    html += '<option value="' + t.val + '">' + t.label + s + '</option>';
  });
  if (specFiltered.length > 0) {
    specFiltered.forEach(function(t) {
      var s = t.seuil !== null ? ' (<=' + (t.seuil < 0 ? '' : '+') + t.seuil + 'C)' : ' (Manuel)';
      html += '<option value="' + t.val + '">' + t.label + s + '</option>';
    });
  }
  return html;
}
function buildEnceinteBlock(id, nom, type, seuil) {
  var cfg = SEUILS_ENCEINTE[type] || {ico:'🌡️', label:'?'};
  var seuilTxt = seuil !== null ? ((seuil < 0 ? '' : '+') + seuil + '°C') : '?';
  var hasCustomSeuil = (seuil === null);

  // Bloc seuil
  var seuilBlock = '';
  if (!hasCustomSeuil) {
    seuilBlock = '<div id="enc_seuil_info_' + id + '" style="font-size:11px;color:#0891b2;font-weight:600;margin-bottom:10px">Seuil reglementaire : ' + seuilTxt + ' max</div>';
  } else {
    seuilBlock = '<div id="enc_seuil_info_' + id + '" style="font-size:11px;color:#f59e0b;font-weight:600;margin-bottom:8px">Seuil operateur</div>' +
      '<div class="frow" style="margin-bottom:10px"><div class="flabel">Seuil max (°C)</div>' +
        '<div class="tinput-wrap"><input type="number" id="enc_seuil_custom_' + id + '" placeholder="Ex: 25" step="0.5" style="width:100%" oninput="onSeuilCustomChange(\'' + id + '\')"/><div class="tunit">°C</div></div>' +
      '</div>';
  }

  // Bloc affichage seuil dans tcard
  var seuilDisplay = '';
  // Toujours mettre un ID pour permettre la mise à jour dynamique
  if (!hasCustomSeuil) {
    seuilDisplay = '<div class="tcard-seuil" id="enc_seuil_display_' + id + '" style="color:#0891b2">' + seuilTxt + '</div>';
  } else {
    seuilDisplay = '<div class="tcard-seuil" id="enc_seuil_display_' + id + '" style="color:#f59e0b">—</div>';
  }

  return '<div class="fblock" id="enc_block_' + id + '" style="border-left:4px solid #0891b2">' +
    '<div class="fblock-title">' +
      '<span>' + cfg.ico + ' ' + nom + '</span>' +
    '</div>' +
    '<div class="frow" style="margin-bottom:8px">' +
      '<div class="flabel">Localisation / Emplacement</div>' +
      '<input type=\"text\" class=\"finput\" id=\"enc_precision_' + id + '\" data-loc-auto=\"1\" placeholder=\"Ex: Cuisine, Salle, N2...\" style=\"font-size:12px\"/>' +
    '</div>' +
    '<div style="display:flex;gap:8px;margin-bottom:10px;align-items:center">' +
      '<select id="enc_ref_type_' + id + '" data-enc-id="' + id + '" onchange="onTypeEnceinteChange(this)" style="width:100%;padding:7px 10px;background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:9px;font-size:12px;font-weight:600;color:#0369a1">' +
        buildEnceinteOptions() +
      '</select>' +
      '<div id="enc_nom_custom_wrap_' + id + '" style="display:none;margin-top:6px;width:100%">' +
        '<input type="text" id="enc_nom_custom_' + id + '" placeholder="Nom équipement (ex: Armoire pâtisserie)" style="width:100%;padding:7px 10px;background:#fff8f0;border:1.5px solid #fed7aa;border-radius:9px;font-size:12px;color:#c2410c;font-family:Outfit,sans-serif"/>' +
      '</div>' +
      '<input type="text" id="enc_ref_num_' + id + '" placeholder="N° Réf." style="width:80px;padding:7px 10px;background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:9px;font-size:12px;color:#0369a1;font-family:Outfit,sans-serif"/>' +
    '</div>' +
    seuilBlock +
    '<div class="tgrid">' +
      '<div class="tcard">' +
        '<div class="tcard-lbl">T° relevee</div>' +
        '<div class="tinput-wrap"><input type="number" id="enc_temp_' + id + '" placeholder="0" step="0.1" data-enc-id="' + id + '" data-enc-seuil="' + (seuil !== null ? seuil : '') + '" oninput="checkTempEnceinteEl(this)"/><div class="tunit">°C</div></div>' +
      '</div>' +
      '<div class="tcard">' +
        '<div class="tcard-lbl">Seuil max</div>' +
        seuilDisplay +
      '</div>' +
    '</div>' +
    '<div class="conformite-badge pending" id="enc_conf_' + id + '" style="margin-top:8px">Saisissez la temperature</div>' +
    '<div class="nc-auto" id="enc_nc_' + id + '" style="display:none">⚡ NC automatique — temperature hors seuil</div>' +
    buildNCAction('enc_nc_' + id) +
  '</div>';
}


function onTypeEnceinteChange(selectEl) {
  var id = selectEl.getAttribute('data-enc-id');
  var type = selectEl.value;
  var cfg = SEUILS_ENCEINTE[type] || {seuil:null, label:'Manuel', ico:'🔧'};

  // Mettre à jour l'affichage du seuil
  var seuilDisplay = document.getElementById('enc_seuil_display_' + id);
  var seuilInfoEl = document.getElementById('enc_seuil_info_' + id);
  var tempInput = document.getElementById('enc_temp_' + id);

  // Mettre à jour le seuil dans le tcard
  if (seuilDisplay) {
    if (cfg.seuil !== null) {
      var seuilTxt = (cfg.seuil < 0 ? '' : '+') + cfg.seuil + '°C';
      seuilDisplay.textContent = seuilTxt;
      seuilDisplay.style.color = '#0891b2';
    } else {
      seuilDisplay.textContent = 'Manuel';
      seuilDisplay.style.color = '#f59e0b';
    }
  }

  // Mettre à jour le texte du seuil réglementaire
  if (seuilInfoEl) {
    if (cfg.seuil !== null) {
      seuilInfoEl.textContent = 'Seuil reglementaire : ' + (cfg.seuil < 0 ? '' : '+') + cfg.seuil + '°C max';
      seuilInfoEl.style.color = '#0891b2';
    } else {
      seuilInfoEl.textContent = 'Seuil operateur';
      seuilInfoEl.style.color = '#f59e0b';
    }
  }

  // Mettre à jour data-enc-seuil sur l'input temp
  if (tempInput) {
    tempInput.setAttribute('data-enc-seuil', cfg.seuil !== null ? cfg.seuil : '');
    // Recalculer conformité si temp déjà saisie
    if (tempInput.value) checkTempEnceinteEl(tempInput);
  }

  // Afficher champ nom libre si Autre équipement
  var nomWrap = document.getElementById('enc_nom_custom_wrap_' + id);
  if (nomWrap) {
    nomWrap.style.display = (type === 'autre' || type === '') ? 'block' : 'none';
  }

  // Mettre à jour le titre du bloc
  var titleEl = document.querySelector('#enc_block_' + id + ' .fblock-title span');
  if (titleEl && type) {
    var ico = cfg.ico || '🌡️';
    // Garder le nom actuel mais mettre à jour l'icône
    var currentText = titleEl.textContent;
    var namePart = currentText.replace(/^.\s*/, '').trim();
    titleEl.textContent = ico + ' ' + namePart;
  }
}

function onSeuilCustomChange(id) {
  var customEl = document.getElementById('enc_seuil_custom_' + id);
  var dispEl = document.getElementById('enc_seuil_display_' + id);
  if (!customEl || !customEl.value) return;
  var seuil = parseFloat(customEl.value);
  if (dispEl) dispEl.textContent = '+' + seuil + '°C';
  checkTempEnceinte(id, seuil);
}



function checkTempEnceinteEl(el) {
  var id = el.getAttribute('data-enc-id');
  var seuilStr = el.getAttribute('data-enc-seuil');
  var seuil = seuilStr !== '' ? parseFloat(seuilStr) : null;
  checkTempEnceinte(id, seuil);
}
function checkTempEnceinte(id, seuil) {
  var tempEl = document.getElementById('enc_temp_' + id);
  var confEl = document.getElementById('enc_conf_' + id);
  var ncEl   = document.getElementById('enc_nc_' + id);
  if (!tempEl || tempEl.value === '') {
    if (confEl) { confEl.className='conformite-badge pending'; confEl.textContent='Saisissez la température'; }
    if (ncEl) ncEl.style.display = 'none'; hideNCAction(ncEl.id);
    return;
  }
  if (seuil === null) {
    // Tenter de lire le seuil custom saisi par l'opérateur
    var customEl = document.getElementById('enc_seuil_custom_' + id);
    if (customEl && customEl.value) {
      seuil = parseFloat(customEl.value);
  if (!isNaN(parseFloat(tempEl ? tempEl.value : ''))) { var _tv = parseFloat(tempEl.value); if (_tv < -40 || _tv > 200) { showToast('Température implausible', 'warn', 2000); return; } }
      // Mettre à jour l'affichage du seuil
      var seuilDisp = document.getElementById('enc_seuil_display_' + id);
      if (seuilDisp) seuilDisp.textContent = '+' + seuil + '°C';
    } else {
      if (confEl) { confEl.className='conformite-badge pending'; confEl.textContent='Saisissez le seuil ci-dessus'; }
      return;
    }
  }
  var temp = parseFloat(tempEl.value);
  if (temp <= seuil) {
    confEl.className='conformite-badge ok'; confEl.textContent='✓ Conforme';
    ncEl.style.display='none'; hideNCAction(ncEl.id); tempEl.style.borderColor='';
  } else {
    confEl.className='conformite-badge bad'; confEl.textContent='✗ Non conforme — +' + (temp-seuil).toFixed(1) + '°C au-dessus du seuil';
    ncEl.style.display='flex'; showNCAction(ncEl.id); tempEl.style.borderColor='var(--red)';
  }
}

function getBySection(resto, bp, rapide, boucherie, collective) {
  if (SECTEUR_ACTIF === 'bp') return bp !== undefined ? bp : resto;
  if (SECTEUR_ACTIF === 'rapide') return rapide !== undefined ? rapide : resto;
  if (SECTEUR_ACTIF === 'boucherie') return boucherie !== undefined ? boucherie : resto;
  if (SECTEUR_ACTIF === 'collective') return collective !== undefined ? collective : resto;
  return resto;
}

function buildEnceintesPreconfigees() {
  var container = document.getElementById('enceintesPreconfigContainer');
  var list = getBySection(ENCEINTES_PRECONFIG, ENCEINTES_PRECONFIG_BP, ENCEINTES_PRECONFIG_RAPIDE, ENCEINTES_PRECONFIG_BOUCHERIE, ENCEINTES_PRECONFIG_COLLECTIVE);
  container.innerHTML = list.map(function(e) {
    return buildEnceinteBlock(e.id, e.nom, e.type, e.seuil);
  }).join('');
  list.forEach(function(e) { initEnceinteSelect(e.id); });
}

function selTypeEnceinte(type) {
  typeEnceinteCourant = type;
  // Réinitialiser TOUS les boutons de type
  document.querySelectorAll('#typeEnceinte .status-btn').forEach(function(b) {
    b.classList.remove('active-ok');
  });
  // Activer le bouton correspondant
  var map = {
    chambre_froide:'cf', refrigerateur:'rf', congelateur:'cg',
    cellule_refroidissement:'cr', vitrine_refrigeree:'vr', armoire_refrigeree:'ar',
    cellule_pousse:'cp', bain_marie:'bm', four:'fo', friteuse:'fr2', autre:'au'
  };
  var btnId = document.getElementById('te_' + (map[type] || type));
  if (btnId) btnId.classList.add('active-ok');
  // Afficher le seuil automatique
  var cfg = SEUILS_ENCEINTE[type];
}

function ajouterEnceinteDynamique() {
  enceintesDynamiques++;
  var id = 'dyn_' + enceintesDynamiques;
  // V80 — Comptage DOM réel : on compte le nombre TOTAL de blocs enceinte présents (pré-config + ajoutés)
  // pour obtenir un numéro séquentiel cohérent, peu importe le secteur.
  var totalBlocs = document.querySelectorAll('#page-temperatures [id^="enc_block_"]').length;
  var num = totalBlocs + 1;
  var nom = 'Enceinte N°' + num;
  var container = document.getElementById('enceintesDynamiquesContainer');
  var div = document.createElement('div');
  div.innerHTML = buildEnceinteBlock(id, nom, '', null);
  container.appendChild(div.firstElementChild);
  initEnceinteSelect(id);
  setTimeout(function() {
    var el = document.getElementById('enc_block_' + id);
    if (el) el.scrollIntoView({behavior:'smooth', block:'start'});
  }, 100);
}

function initSigTemp() {
  sigCanvasTemp = document.getElementById('sigCanvasTemp');
  if (!sigCanvasTemp) return;
  sigCtxTemp = sigCanvasTemp.getContext('2d');
  hasSigTemp = false; isDrawingTemp = false;
  var dpr = window.devicePixelRatio || 1;
  var w = sigCanvasTemp.parentElement.clientWidth || 340;
  sigCanvasTemp.width = Math.round(w * dpr);
  sigCanvasTemp.height = Math.round(140 * dpr);
  sigCanvasTemp.style.width = w + 'px';
  sigCanvasTemp.style.height = '140px';
  sigCtxTemp.scale(dpr, dpr);
  sigCtxTemp.strokeStyle = '#1a1a2e';
  sigCtxTemp.lineWidth = 2.5;
  sigCtxTemp.lineCap = 'round';
  sigCtxTemp.lineJoin = 'round';
  function pos(e) { var r=sigCanvasTemp.getBoundingClientRect(); var s=e.touches?e.touches[0]:e; return {x:s.clientX-r.left,y:s.clientY-r.top}; }
  function start(e){e.preventDefault();isDrawingTemp=true;var p=pos(e);sigCtxTemp.beginPath();sigCtxTemp.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingTemp)return;var p=pos(e);sigCtxTemp.lineTo(p.x,p.y);sigCtxTemp.stroke();hasSigTemp=true;}
  function stop(e){e.preventDefault();isDrawingTemp=false;}
  sigCanvasTemp.addEventListener('mousedown',start);
  sigCanvasTemp.addEventListener('mousemove',move);
  sigCanvasTemp.addEventListener('mouseup',stop);
  sigCanvasTemp.addEventListener('mouseleave',stop);
  sigCanvasTemp.addEventListener('touchstart',start,{passive:false});
  sigCanvasTemp.addEventListener('touchmove',move,{passive:false});
  sigCanvasTemp.addEventListener('touchend',stop,{passive:false});
}

function clearSigTemp() {
  if (!sigCtxTemp||!sigCanvasTemp) return;
  sigCtxTemp.clearRect(0,0,sigCanvasTemp.width,sigCanvasTemp.height);
  hasSigTemp=false;
}

async function validerTemperatures() {
  var prenom = document.getElementById('temp_sig_prenom').value.trim();
  var nom = document.getElementById('temp_sig_nom').value.trim();
  var reqEl = document.getElementById('temp_sig_required');
  if (!hasSigTemp || !prenom || !nom) {
    reqEl.style.display='flex';
    reqEl.scrollIntoView({behavior:'smooth',block:'center'});
    return;
  }
  reqEl.style.display='none';
  // V113 — D : Sauvegarde Supabase AVANT PDF (awaited, après check signature)
  if (SB_READY && ETAB_ID) {
    try {
      await sbSauvegarderModule('temperatures', {secteur: SECTEUR_ACTIF, etab: ETAB.nom, timestamp: new Date().toISOString()}, prenom + ' ' + nom);
    } catch(eSB) { console.warn('Supabase save error (temperatures):', eSB); }
  }
  // Collect data
  var relevees = [];
  var allEnceintes = document.querySelectorAll('[id^="enc_block_"]');
  allEnceintes.forEach(function(block) {
    var id = block.id.replace('enc_block_','');
    var tempEl = document.getElementById('enc_temp_' + id);
    var confEl = document.getElementById('enc_conf_' + id);
    relevees.push({
      nom: block.querySelector('.fblock-title span') ? block.querySelector('.fblock-title span').textContent : id,
      temp: tempEl ? tempEl.value || '—' : '—',
      conformite: confEl ? confEl.textContent : '—',
    });
  });
  tempPdfData = {
    timestamp: getNowStr(),
    signataire: prenom + ' ' + nom,
    obs: document.getElementById('temp_obs').value || '',
    relevees: relevees,
  };
  document.getElementById('modalTempPdf').classList.add('visible');
  sauvegarderHistorique('Températures enceintes', document.getElementById('temp_sig_prenom') ? document.getElementById('temp_sig_prenom').value : '');
  sauvegarderDonnesModule('page-temperatures');
  stopBrouillonAuto(); effacerBrouillon('page-temperatures');
}

function downloadTempPDF() {
  imprimerTemperatures();
}

function confirmerSansTempPDF() {
  showConfirm('🌡️', 'Températures — sans PDF', 'Sans PDF vous n\'avez pas de preuve legale. Continuez seulement si vous imprimez ce document.', 'Continuer quand même', '', function(ok){ if(ok) fermerModalTemp(); });
}
function fermerModalTemp() {
  document.getElementById('modalTempPdf').classList.remove('visible');
  showPage('page-guide');
}

