var sigCanvasOuv, sigCtxOuv, isDrawingOuv = false, hasSigOuv = false;

function showOuvNC(actif) {
  var block = document.getElementById('ouv_nc_block');
  var oui = document.getElementById('ouv_nc_oui');
  var non = document.getElementById('ouv_nc_non');
  if (block) block.style.display = actif ? 'block' : 'none';
  if (oui) oui.classList.toggle('active-bad', actif);
  if (non) non.classList.toggle('active-ok', !actif);
  if (actif) {
    var now = new Date();
    var heureEl = document.getElementById('ouv_nc_heure');
    if (heureEl && !heureEl.value) heureEl.value = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
  }
}

function initSigOuv() {
  sigCanvasOuv = document.getElementById('sigCanvasOuv');
  if (!sigCanvasOuv) return;
  sigCtxOuv = sigCanvasOuv.getContext('2d');
  hasSigOuv = false; isDrawingOuv = false;
  var dpr = window.devicePixelRatio || 1;
  var w = sigCanvasOuv.parentElement.clientWidth || 340;
  sigCanvasOuv.width = Math.round(w * dpr);
  sigCanvasOuv.height = Math.round(140 * dpr);
  sigCanvasOuv.style.width = w + 'px';
  sigCanvasOuv.style.height = '140px';
  sigCtxOuv.scale(dpr, dpr);
  sigCtxOuv.strokeStyle = '#1a1a2e'; sigCtxOuv.lineWidth = 2.5;
  sigCtxOuv.lineCap = 'round'; sigCtxOuv.lineJoin = 'round';
  function pos(e){var r=sigCanvasOuv.getBoundingClientRect();var s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top};}
  function start(e){e.preventDefault();isDrawingOuv=true;var p=pos(e);sigCtxOuv.beginPath();sigCtxOuv.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingOuv)return;var p=pos(e);sigCtxOuv.lineTo(p.x,p.y);sigCtxOuv.stroke();hasSigOuv=true;}
  function stop(e){e.preventDefault();isDrawingOuv=false;}
  sigCanvasOuv.addEventListener('mousedown',start);
  sigCanvasOuv.addEventListener('mousemove',move);
  sigCanvasOuv.addEventListener('mouseup',stop);
  sigCanvasOuv.addEventListener('mouseleave',stop);
  sigCanvasOuv.addEventListener('touchstart',start,{passive:false});
  sigCanvasOuv.addEventListener('touchmove',move,{passive:false});
  sigCanvasOuv.addEventListener('touchend',stop,{passive:false});
}

function clearSigOuv() {
  if (!sigCtxOuv||!sigCanvasOuv) return;
  sigCtxOuv.clearRect(0,0,sigCanvasOuv.width,sigCanvasOuv.height);
  hasSigOuv = false;
}

// V113 — J : Bloquer validation si NC visible sans action corrective remplie
function verifierNCActionsRemplies(pageId) {
  var page = document.getElementById(pageId);
  if (!page) return true;
  var ncActions = page.querySelectorAll('.nc-action');
  for (var i = 0; i < ncActions.length; i++) {
    var nca = ncActions[i];
    // Visible si offsetParent non-null (gère class .visible ET inline style)
    if (!nca.offsetParent) continue;
    var sel = nca.querySelector('select');
    var detailEl = nca.querySelector('input[type="text"]');
    var typeOk = (sel && sel.selectedIndex > 0);
    var detailOk = (detailEl && detailEl.value.trim() !== '');
    if (!typeOk && !detailOk) {
      // Trouver libellé de la NC concernée (frère précédent)
      var label = '';
      var prev = nca.previousElementSibling;
      while (prev && !label) {
        var ncAuto = prev.classList && prev.classList.contains('nc-auto') ? prev : (prev.querySelector ? prev.querySelector('.nc-auto') : null);
        if (ncAuto && ncAuto.offsetParent) { label = ncAuto.textContent.replace(/[⚡⚠️🚨]/g,'').trim().substring(0,60); break; }
        var flab = prev.querySelector ? prev.querySelector('.flabel') : null;
        if (flab) { label = flab.textContent.replace(/[⚡⚠️🚨*★]/g,'').trim().substring(0,60); break; }
        prev = prev.previousElementSibling;
      }
      nca.scrollIntoView({behavior:'smooth', block:'center'});
      var savedShadow = nca.style.boxShadow;
      nca.style.boxShadow = '0 0 0 3px #dc2626';
      setTimeout(function(el, s){ el.style.boxShadow = s; }, 3000, nca, savedShadow);
      showToast('Action corrective requise' + (label ? ' : ' + label : ''), 'err');
      return false;
    }
  }
  return true;
}

async function validerOuverture() {
  // V113 — J : bloquer si NC visible sans action corrective remplie
  if (!verifierNCActionsRemplies('page-ouverture')) return;
  var prenom = document.getElementById('ouv_sig_prenom').value.trim();
  var nom = document.getElementById('ouv_sig_nom').value.trim();
  var reqEl = document.getElementById('ouv_sig_required');
  if (!hasSigOuv || !prenom || !nom) {
    reqEl.style.display = 'flex';
    reqEl.scrollIntoView({behavior:'smooth',block:'center'});
    return;
  }
  reqEl.style.display = 'none';
  // V113 — D : Sauvegarde Supabase AVANT PDF (awaited, après check signature)
  if (SB_READY && ETAB_ID) {
    try {
      await sbSauvegarderModule('ouverture', {secteur: SECTEUR_ACTIF, etab: ETAB.nom, timestamp: new Date().toISOString()}, prenom + ' ' + nom);
    } catch(eSB) { console.warn('Supabase save error (ouverture):', eSB); }
  }
  document.getElementById('modalOuvPdf').classList.add('visible');
  sauvegarderHistorique('Nettoyage ouverture', prenom);
  sauvegarderDonnesModule('page-ouverture');
  stopBrouillonAuto(); effacerBrouillon('page-ouverture');
}

function downloadOuvPDF() {
  imprimerModule('page-ouverture', 'Nettoyage Ouverture');
}

function confirmerSansOuvPDF() {
  showConfirm('🌅', 'Nettoyage ouverture — sans PDF', 'Sans PDF vous n\'avez pas de preuve legale. Continuez seulement si vous imprimez ce document.', 'Continuer quand même', '', function(ok){ if(ok) fermerModalOuv(); });
}
function fermerModalOuv() {
  document.getElementById('modalOuvPdf').classList.remove('visible');
  showPage('page-guide');
}

