function supprimerPlat(id) {
  if (!confirm('Confirmer la suppression ?')) return;
  var el = document.getElementById('plat_' + id);
  if (el) el.remove();
  renumeroterBlocs('#cuisPlatContainer', 'Plat N°');
}

function onCuissonType(id) {
  var sel = document.getElementById('plat_type_' + id);
  var val = sel.value;
  var customDiv = document.getElementById('plat_custom_' + id);
  var seuilDiv = document.getElementById('plat_seuil_display_' + id);
  var seuilVal = document.getElementById('plat_seuil_val_' + id);
  customDiv.style.display = val === 'custom' ? 'block' : 'none';
  if (!val || val === 'custom') { seuilDiv.style.display = 'none'; return; }
  seuilDiv.style.display = 'flex';
  // Afficher le seuil avec la bonne unité selon le secteur
  if (SECTEUR_ACTIF === 'bp') {
    var types = TYPES_CUISSON_BP;
    var found = types.find(function(t){ return String(t.seuil) === val; });
    seuilVal.textContent = found ? val + (found.seuilMax ? '-' + found.seuilMax : '') + ' ' + found.unite : val + '°C';
  } else if (SECTEUR_ACTIF === 'rapide' || SECTEUR_ACTIF === 'boucherie' || SECTEUR_ACTIF === 'collective') {
    var typesR = TYPES_CUISSON_RAPIDE;
    var foundR = typesR.find(function(t){ return String(t.seuil) === val; });
    var typesRList = getBySection(TYPES_VIANDE, TYPES_CUISSON_BP, TYPES_CUISSON_RAPIDE, TYPES_CUISSON_BOUCHERIE, TYPES_CUISSON_COLLECTIVE);
    var foundR2 = typesRList.find(function(t){ return String(t.seuil) === val; });
    seuilVal.textContent = foundR2 ? 'Min. ' + val + ' ' + foundR2.unite : val + '°C';
  } else {
    seuilVal.textContent = 'Min. +' + val + '°C cœur';
  }
  checkCuissonConf(id);
}

function checkCuissonConf(id) {
  var typeVal = document.getElementById('plat_type_' + id).value;
  var tempEl = document.getElementById('plat_temp_' + id);
  var confEl = document.getElementById('plat_conf_' + id);
  var ncEl = document.getElementById('plat_nc_' + id);
  if (!typeVal || typeVal === '' || typeVal === 'custom' || !tempEl.value) {
    confEl.className = 'conformite-badge pending'; confEl.textContent = 'Saisissez la T°';
    ncEl.style.display = 'none'; hideNCAction(ncEl.id); return;
  }
  var seuil = parseFloat(typeVal);
  var temp = parseFloat(tempEl.value);
  if (SECTEUR_ACTIF === 'bp') {
    // Pour la boulangerie : T° four, on vérifie que c'est dans la plage
    var found = TYPES_CUISSON_BP.find(function(t){ return String(t.seuil) === typeVal; });
    var max = found && found.seuilMax ? found.seuilMax : seuil + 50;
    if (temp >= seuil && temp <= max) {
      confEl.className = 'conformite-badge ok'; confEl.textContent = '✓ T° four conforme';
      ncEl.style.display = 'none'; hideNCAction(ncEl.id); tempEl.style.borderColor = '';
    } else if (temp < seuil) {
      confEl.className = 'conformite-badge bad'; confEl.textContent = '✗ T° four trop basse — min. ' + seuil + '°C';
      ncEl.style.display = 'flex'; showNCAction(ncEl.id); tempEl.style.borderColor = 'var(--red)';
    } else {
      confEl.className = 'conformite-badge bad'; confEl.textContent = '✗ T° four trop élevée — max. ' + max + '°C';
      ncEl.style.display = 'flex'; showNCAction(ncEl.id); tempEl.style.borderColor = 'var(--red)';
    }
  } else {
    // Resto & rapide : T° cœur minimum
    if (temp >= seuil) {
      confEl.className = 'conformite-badge ok'; confEl.textContent = '✓ T° cœur conforme';
      ncEl.style.display = 'none'; hideNCAction(ncEl.id); tempEl.style.borderColor = '';
    } else {
      confEl.className = 'conformite-badge bad'; confEl.textContent = '✗ NC — ' + (seuil - temp).toFixed(1) + '°C manquants';
      ncEl.style.display = 'flex'; showNCAction(ncEl.id); tempEl.style.borderColor = 'var(--red)';
    }
  }
}

function toggleRemise(id, show, btn) {
  var oui = document.getElementById('remise_oui_' + id);
  var non = document.getElementById('remise_non_' + id);
  var zone = document.getElementById('remise_zone_' + id);
  if (oui) oui.classList.remove('active-ok','active-warn');
  if (non) non.classList.remove('active-ok','active-warn');
  if (show) { if (oui) oui.classList.add('active-ok'); zone.style.display = 'block'; }
  else { if (non) non.classList.add('active-warn'); zone.style.display = 'none'; }
}

function checkRemise(id) {
  var tf = parseFloat(document.getElementById('remise_tf_' + id).value);
  var confEl = document.getElementById('remise_conf_' + id);
  var ncEl = document.getElementById('remise_nc_' + id);
  if (isNaN(tf)) { confEl.className='conformite-badge pending'; confEl.textContent='Saisissez les températures'; ncEl.style.display='none'; hideNCAction(ncEl.id); return; }
  if (tf >= 63) {
    confEl.className='conformite-badge ok'; confEl.textContent='✓ Conforme — +63°C atteint';
    ncEl.style.display='none'; hideNCAction(ncEl.id);
  } else {
    confEl.className='conformite-badge bad'; confEl.textContent='✗ NC — +63°C non atteint';
    ncEl.style.display='flex'; showNCAction(ncEl.id);
  }
}

function initSigCuis() {
  sigCanvasCuis = document.getElementById('sigCanvasCuis');
  if (!sigCanvasCuis) return;
  sigCtxCuis = sigCanvasCuis.getContext('2d');
  hasSigCuis = false; isDrawingCuis = false;
  var dpr = window.devicePixelRatio || 1;
  var w = sigCanvasCuis.parentElement.clientWidth || 340;
  sigCanvasCuis.width = Math.round(w * dpr);
  sigCanvasCuis.height = Math.round(140 * dpr);
  sigCanvasCuis.style.width = w + 'px';
  sigCanvasCuis.style.height = '140px';
  sigCtxCuis.scale(dpr, dpr);
  sigCtxCuis.strokeStyle = '#1a1a2e'; sigCtxCuis.lineWidth = 2.5;
  sigCtxCuis.lineCap = 'round'; sigCtxCuis.lineJoin = 'round';
  function pos(e){var r=sigCanvasCuis.getBoundingClientRect();var s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top};}
  function start(e){e.preventDefault();isDrawingCuis=true;var p=pos(e);sigCtxCuis.beginPath();sigCtxCuis.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingCuis)return;var p=pos(e);sigCtxCuis.lineTo(p.x,p.y);sigCtxCuis.stroke();hasSigCuis=true;}
  function stop(e){e.preventDefault();isDrawingCuis=false;}
  sigCanvasCuis.addEventListener('mousedown',start); sigCanvasCuis.addEventListener('mousemove',move);
  sigCanvasCuis.addEventListener('mouseup',stop); sigCanvasCuis.addEventListener('mouseleave',stop);
  sigCanvasCuis.addEventListener('touchstart',start,{passive:false}); sigCanvasCuis.addEventListener('touchmove',move,{passive:false});
  sigCanvasCuis.addEventListener('touchend',stop,{passive:false});
}

function clearSigCuis() {
  if (!sigCtxCuis||!sigCanvasCuis) return;
  sigCtxCuis.clearRect(0,0,sigCanvasCuis.width,sigCanvasCuis.height); hasSigCuis=false;
}

