function checkRefroi(id) {
  var t0El = document.getElementById('refroi_t0_' + id);
  var t2El = document.getElementById('refroi_t2_' + id);
  var confEl = document.getElementById('refroi_conf_' + id);
  var ncEl = document.getElementById('refroi_nc_' + id);

  if (!t2El || t2El.value === '') {
    confEl.className='conformite-badge pending';
    confEl.textContent='Saisissez les deux températures';
    ncEl.style.display='none'; hideNCAction(ncEl.id); return;
  }

  // Vérification T0 — alerte si < 63°C
  var t0Warn = document.getElementById('refroi_t0_warn_' + id);
  if (t0El && t0El.value !== '') {
    var t0 = parseFloat(t0El.value);
    if (!t0Warn) {
      t0Warn = document.createElement('div');
      t0Warn.id = 'refroi_t0_warn_' + id;
      t0Warn.style.cssText = 'font-size:11px;font-weight:600;margin-top:4px;padding:4px 8px;border-radius:6px;display:none';
      t0El.parentElement.appendChild(t0Warn);
    }
    if (t0 < 63) {
      t0Warn.style.display = 'block';
      t0Warn.style.background = '#fff8f8';
      t0Warn.style.color = '#dc2626';
      t0Warn.textContent = '⚠️ T° initiale < +63°C — Le refroidissement rapide s\'applique à partir de +63°C';
    } else {
      t0Warn.style.display = 'none';
    }
  }

  var t2 = parseFloat(t2El.value);

  if (t2 <= 10) {
    // Conforme pour le refroidissement
    if (SECTEUR_ACTIF === 'bp' && t2 > 4) {
      // BP : conforme refroidissement mais stockage final insuffisant
      confEl.className='conformite-badge pending';
      confEl.textContent='⚠️ Refroidissement OK (+10°C atteint) — Mais stocker à +4°C max pour crèmes/entremets';
      t2El.style.borderColor='var(--yellow)';
    } else {
      confEl.className='conformite-badge ok';
      confEl.textContent='✓ Conforme — Refroidissement atteint en 2h';
      t2El.style.borderColor='';
    }
    ncEl.style.display='none'; hideNCAction(ncEl.id);
  } else {
    // Non conforme — seuil +10°C non atteint
    confEl.className='conformite-badge bad';
    confEl.textContent='✗ NC — Refroidissement insuffisant : ' + t2.toFixed(1) + '°C relevé (max +10°C requis)';
    ncEl.textContent = '⚡ NC automatique — Refroidissement insuffisant : +' + t2.toFixed(1) + '°C à T+2h (seuil +10°C dépassé)';
    ncEl.style.display='flex'; showNCAction(ncEl.id); t2El.style.borderColor='var(--red)';
  }
}

function initSigRefroi() {
  sigCanvasRefroi = document.getElementById('sigCanvasRefroi');
  if (!sigCanvasRefroi) return;
  sigCtxRefroi = sigCanvasRefroi.getContext('2d');
  hasSigRefroi = false; isDrawingRefroi = false;
  var dpr = window.devicePixelRatio || 1;
  var w = sigCanvasRefroi.parentElement.clientWidth || 340;
  sigCanvasRefroi.width = Math.round(w*dpr); sigCanvasRefroi.height = Math.round(140*dpr);
  sigCanvasRefroi.style.width = w+'px'; sigCanvasRefroi.style.height = '140px';
  sigCtxRefroi.scale(dpr,dpr); sigCtxRefroi.strokeStyle='#1a1a2e';
  sigCtxRefroi.lineWidth=2.5; sigCtxRefroi.lineCap='round'; sigCtxRefroi.lineJoin='round';
  function pos(e){var r=sigCanvasRefroi.getBoundingClientRect();var s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top};}
  function start(e){e.preventDefault();isDrawingRefroi=true;var p=pos(e);sigCtxRefroi.beginPath();sigCtxRefroi.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingRefroi)return;var p=pos(e);sigCtxRefroi.lineTo(p.x,p.y);sigCtxRefroi.stroke();hasSigRefroi=true;}
  function stop(e){e.preventDefault();isDrawingRefroi=false;}
  sigCanvasRefroi.addEventListener('mousedown',start); sigCanvasRefroi.addEventListener('mousemove',move);
  sigCanvasRefroi.addEventListener('mouseup',stop); sigCanvasRefroi.addEventListener('mouseleave',stop);
  sigCanvasRefroi.addEventListener('touchstart',start,{passive:false}); sigCanvasRefroi.addEventListener('touchmove',move,{passive:false});
  sigCanvasRefroi.addEventListener('touchend',stop,{passive:false});
}

function clearSigRefroi() {
  if (!sigCtxRefroi||!sigCanvasRefroi) return;
  sigCtxRefroi.clearRect(0,0,sigCanvasRefroi.width,sigCanvasRefroi.height); hasSigRefroi=false;
}

