function supprimerFriteuse(id) {
  if (!confirm('Confirmer la suppression ?')) return;
  var el = document.getElementById('friteuse_' + id);
  if (el) el.remove();
  renumeroterBlocs('#huileContainer', 'Friteuse N°');
}

function checkHuile(id) {
  var tempEl = document.getElementById('fr_temp_' + id);
  var tpmEl = document.getElementById('fr_tpm_' + id);
  var confEl = document.getElementById('fr_conf_' + id);
  var actionTemp = document.getElementById('fr_action_temp_' + id);
  var actionTpm = document.getElementById('fr_action_tpm_' + id);

  if (!tempEl.value && !tpmEl.value) {
    confEl.className='conformite-badge pending';
    confEl.textContent='Saisissez la température et le TPM';
    if (actionTemp) actionTemp.style.display='none';
    if (actionTpm) actionTpm.style.display='none';
    return;
  }

  var tempNC = tempEl.value && parseFloat(tempEl.value) > 175;
  var tpmNC  = tpmEl.value  && parseFloat(tpmEl.value)  > 25;

  // Couleur bordure
  if (tempEl.value) tempEl.style.borderColor = tempNC ? 'var(--red)' : '';
  if (tpmEl.value)  tpmEl.style.borderColor  = tpmNC  ? 'var(--red)' : '';

  // Afficher les zones d'action appropriées
  if (actionTemp) actionTemp.style.display = tempNC ? 'block' : 'none';
  if (actionTpm)  actionTpm.style.display  = tpmNC  ? 'block' : 'none';

  if (tempNC || tpmNC) {
    var msgs = [];
    if (tempNC) msgs.push('T° > 175°C → baisser thermostat');
    if (tpmNC)  msgs.push('TPM > 25% → changer l\'huile');
    confEl.className='conformite-badge bad';
    confEl.textContent='✗ NC — ' + msgs.join(' | ');
  } else {
    confEl.className='conformite-badge ok';
    confEl.textContent='✓ Conforme';
  }
}

function initSigHuile() {
  sigCanvasHuile = document.getElementById('sigCanvasHuile');
  if (!sigCanvasHuile) return;
  sigCtxHuile = sigCanvasHuile.getContext('2d');
  hasSigHuile = false; isDrawingHuile = false;
  var dpr = window.devicePixelRatio || 1, w = sigCanvasHuile.parentElement.clientWidth || 340;
  sigCanvasHuile.width = Math.round(w * dpr); sigCanvasHuile.height = Math.round(140 * dpr);
  sigCanvasHuile.style.width = w + 'px'; sigCanvasHuile.style.height = '140px';
  sigCtxHuile.scale(dpr, dpr);
  sigCtxHuile.strokeStyle = '#0f172a'; sigCtxHuile.lineWidth = 2.5; sigCtxHuile.lineCap = 'round';
  function getPos(e) {
    var r = sigCanvasHuile.getBoundingClientRect();
    var src = e.touches ? e.touches[0] : e;
    return { x: src.clientX - r.left, y: src.clientY - r.top };
  }
  sigCanvasHuile.addEventListener('mousedown', function(e) { isDrawingHuile = true; hasSigHuile = true; var p = getPos(e); sigCtxHuile.beginPath(); sigCtxHuile.moveTo(p.x, p.y); });
  sigCanvasHuile.addEventListener('mousemove', function(e) { if (!isDrawingHuile) return; var p = getPos(e); sigCtxHuile.lineTo(p.x, p.y); sigCtxHuile.stroke(); });
  sigCanvasHuile.addEventListener('mouseup', function() { isDrawingHuile = false; });
  sigCanvasHuile.addEventListener('touchstart', function(e) { e.preventDefault(); isDrawingHuile = true; hasSigHuile = true; var p = getPos(e); sigCtxHuile.beginPath(); sigCtxHuile.moveTo(p.x, p.y); }, {passive:false});
  sigCanvasHuile.addEventListener('touchmove', function(e) { e.preventDefault(); if (!isDrawingHuile) return; var p = getPos(e); sigCtxHuile.lineTo(p.x, p.y); sigCtxHuile.stroke(); }, {passive:false});
  sigCanvasHuile.addEventListener('touchend', function() { isDrawingHuile = false; });
}

function clearSigHuile() {
  if (sigCtxHuile && sigCanvasHuile) { sigCtxHuile.clearRect(0, 0, sigCanvasHuile.width, sigCanvasHuile.height); hasSigHuile = false; }
}

async function validerHuiles() {
  var prenom = document.getElementById('huile_sig_prenom').value.trim();
  var nom = document.getElementById('huile_sig_nom').value.trim();
  var reqEl = document.getElementById('huile_sig_required');
  if (!hasSigHuile || !prenom || !nom) { reqEl.style.display = 'flex'; reqEl.scrollIntoView({behavior:'smooth', block:'center'}); return; }
  reqEl.style.display = 'none';
  // V113 — D : Sauvegarde Supabase AVANT PDF (awaited)
  if (SB_READY && ETAB_ID) {
    try {
      await sbSauvegarderModule('huiles', {secteur: SECTEUR_ACTIF, etab: ETAB.nom, timestamp: new Date().toISOString()}, prenom + ' ' + nom);
    } catch(eSB) { console.warn('Supabase save error (huiles):', eSB); }
  }
  huilePdfData = { timestamp: getNowStr(), signataire: prenom + ' ' + nom, friteuses: [] };
  // IDs réels dans ajouterFriteuse : fr_nom_, fr_huile_, fr_temp_, fr_tpm_, fr_conf_
  document.querySelectorAll('[id^="friteuse_"]').forEach(function(block) {
    var id = block.id.replace('friteuse_', '');
    var nomEl = document.getElementById('fr_nom_' + id);
    var huileEl = document.getElementById('fr_huile_' + id);
    var tempEl = document.getElementById('fr_temp_' + id);
    var tpmEl = document.getElementById('fr_tpm_' + id);
    var confEl = document.getElementById('fr_conf_' + id);
    huilePdfData.friteuses.push({
      num: id,
      type: (huileEl ? huileEl.value : '') || 'Non renseigne',
      nom: (nomEl ? nomEl.value : '') || '',
      temp: (tempEl ? tempEl.value : '') || '—',
      tpm: (tpmEl ? tpmEl.value : '') || '—',
      conformite: confEl ? confEl.textContent : '—',
    });
  });
  document.getElementById('modalHuilePdf').classList.add('visible');
  sauvegarderHistorique('Huiles de friture', document.getElementById('huile_sig_prenom') ? document.getElementById('huile_sig_prenom').value : '');
  sauvegarderDonnesModule('page-huiles');
  stopBrouillonAuto(); effacerBrouillon('page-huiles');
}

