// ── BASE INGRÉDIENTS PERSONNALISÉS (localStorage) ──
var CUSTOM_INGREDIENTS = {};
try {
  var stored = lsGet('haccp_custom_ingredients');
  if (stored) CUSTOM_INGREDIENTS = JSON.parse(stored);
} catch(e) {}

function saveCustomIngredients() {
  try { lsSet('haccp_custom_ingredients', JSON.stringify(CUSTOM_INGREDIENTS)); } catch(e) {}
}

