// MODULE 15 — NC & ACTIONS CORRECTIVES
// ══════════════════════════════
var sigCanvasNC, sigCtxNC, isDrawingNC = false, hasSigNC = false;
var ncCount = 0;

var MODULES_NC = [
  'Réception & Traçabilité','Températures Enceintes','Hygiène Personnel',
  'Nettoyage Ouverture','Cuisson & Remise T°','Refroidissement Rapide',
  'Huiles Friture','Étiquetage Interne','Nettoyage Fermeture',
  'Pertes & Invendus','Déchets & Biodéchets','Nuisibles',
  'Contrôle Documentaire','Affichage Réglementaire','Autre',
];

// ── TIAC — Restauration collective ──
function showTIACBlock() {
  var block = document.getElementById('tiac_block');
  if (block) block.style.display = SECTEUR_ACTIF === 'collective' ? 'block' : 'none';
}

function activerTIAC(actif) {
  var proc = document.getElementById('tiac_procedure');
  var oui = document.getElementById('tiac_oui');
  var non = document.getElementById('tiac_non');
  if (proc) proc.style.display = actif ? 'block' : 'none';
  if (oui) oui.classList.toggle('active-bad', actif);
  if (non) non.classList.toggle('active-ok', !actif);

  // Afficher aussi la NC TIAC + son action corrective si TIAC activée
  if (proc) {
    var ncAutoTiac = proc.querySelector('.nc-auto');
    var ncActionTiac = document.getElementById('nc_action_tiac');
    if (ncAutoTiac) ncAutoTiac.style.display = actif ? 'flex' : 'none';
    if (ncActionTiac) {
      if (actif) ncActionTiac.classList.add('visible');
      else ncActionTiac.classList.remove('visible');
    }
  }
}

function ajouterNC() {
  ncCount++;
  var id = ncCount;
  var container = document.getElementById('ncContainer');
  var div = document.createElement('div');
  div.className = 'fblock';
  div.id = 'nc_item_' + id;
  div.style.borderLeft = '4px solid #dc2626';
  var delBtn = '<button class="btn-delete" onclick="supprimerNC(' + id + ')">✕</button>';
  var modOpts = MODULES_NC.map(function(m){ return '<option>' + m + '</option>'; }).join('');
  div.innerHTML =
    '<div class="fblock-title"><span>⚠️ NC N°' + id + '</span>' + delBtn + '</div>' +
    '<div class="frow"><div class="flabel">Module concerné</div>' +
      '<select class="fselect" id="nc_module_' + id + '"><option value="">-- Sélectionner --</option>' + modOpts + '</select>' +
    '</div>' +
    '<div class="frow"><div class="flabel">Description de la non-conformité</div>' +
      '<textarea class="ftextarea" id="nc_desc_' + id + '" placeholder="Décrivez précisément ce qui a été constaté..." style="min-height:70px"></textarea>' +
    '</div>' +
    '<div class="frow"><div class="flabel">Gravité</div>' +
      '<div class="status-group">' +
        '<button class="status-btn" onclick="selGravite(' + id + ',\'crit\',this)" style="border-color:#dc2626;color:#dc2626">🔴 Critique</button>' +
        '<button class="status-btn" onclick="selGravite(' + id + ',\'maj\',this)" style="border-color:#f97316;color:#f97316">🟠 Majeure</button>' +
        '<button class="status-btn" onclick="selGravite(' + id + ',\'min\',this)" style="border-color:#f59e0b;color:#92400e">🟡 Mineure</button>' +
      '</div>' +
    '</div>' +
    '<div class="frow"><div class="flabel req">Action corrective mise en place</div>' +
      '<textarea class="ftextarea" id="nc_action_' + id + '" placeholder="Décrivez l\'action corrective effectuée ou prévue..." style="min-height:70px"></textarea>' +
    '</div>' +
    '<div class="tgrid">' +
      '<div class="frow"><div class="flabel">Responsable</div><input class="finput" id="nc_resp_' + id + '" placeholder="Nom & prénom"/></div>' +
      '<div class="frow"><div class="flabel">Date limite de clôture</div><input class="finput" type="date" id="nc_echeance_' + id + '"/></div>' +
    '</div>' +
    '<div class="frow"><div class="flabel">Statut de clôture (NC N°' + id + ')</div>' +
      '<div class="status-group">' +
        '<button class="status-btn" onclick="selHyg(this,\'ok\')">✅ Clôturée</button>' +
        '<button class="status-btn active-warn" onclick="selHyg(this,\'warn\')">🔄 En cours</button>' +
        '<button class="status-btn" onclick="selHyg(this,\'bad\')">⏳ En attente</button>' +
      '</div>' +
    '</div>';
  container.appendChild(div);
  updateNCCounts();
}

function supprimerNC(id) {
  if (!confirm('Confirmer la suppression ?')) return;
  var el = document.getElementById('nc_item_' + id);
  if (el) el.remove();
  updateNCCounts();
  renumeroterBlocs('#ncContainer', 'NC N°');
}

function selGravite(id, gravite, btn) {
  var grp = btn.closest('.status-group');
  grp.querySelectorAll('.status-btn').forEach(function(b){ b.classList.remove('active-ok','active-warn','active-bad'); });
  btn.classList.add(gravite==='crit' ? 'active-bad' : gravite==='maj' ? 'active-warn' : 'active-ok');
  updateNCCounts();
}

function updateNCCounts() {
  var crit=0, maj=0, min=0;
  document.querySelectorAll('[id^="nc_item_"]').forEach(function(block) {
    var id = block.id.replace('nc_item_','');
    var grp = block.querySelector('.status-group');
    if (grp) {
      var activeBad = grp.querySelector('.status-btn.active-bad');
      var activeWarn = grp.querySelector('.status-btn.active-warn');
      var activeOk = grp.querySelector('.status-btn.active-ok');
      if (activeBad) crit++;
      else if (activeWarn) maj++;
      else if (activeOk) min++;
    }
  });
  var cc = document.getElementById('nc_count_crit');
  var cm = document.getElementById('nc_count_maj');
  var cn = document.getElementById('nc_count_min');
  if (cc) cc.textContent = crit;
  if (cm) cm.textContent = maj;
  if (cn) cn.textContent = min;
}

function initSigNC() {
  sigCanvasNC = document.getElementById('sigCanvasNC');
  if (!sigCanvasNC) return;
  sigCtxNC = sigCanvasNC.getContext('2d');
  hasSigNC=false; isDrawingNC=false;
  var dpr=window.devicePixelRatio||1, w=sigCanvasNC.parentElement.clientWidth||340;
  sigCanvasNC.width=Math.round(w*dpr); sigCanvasNC.height=Math.round(140*dpr);
  sigCanvasNC.style.width=w+'px'; sigCanvasNC.style.height='140px';
  sigCtxNC.scale(dpr,dpr); sigCtxNC.strokeStyle='#1a1a2e';
  sigCtxNC.lineWidth=2.5; sigCtxNC.lineCap='round'; sigCtxNC.lineJoin='round';
  function pos(e){var r=sigCanvasNC.getBoundingClientRect();var s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top};}
  function start(e){e.preventDefault();isDrawingNC=true;var p=pos(e);sigCtxNC.beginPath();sigCtxNC.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingNC)return;var p=pos(e);sigCtxNC.lineTo(p.x,p.y);sigCtxNC.stroke();hasSigNC=true;}
  function stop(e){e.preventDefault();isDrawingNC=false;}
  sigCanvasNC.addEventListener('mousedown',start); sigCanvasNC.addEventListener('mousemove',move);
  sigCanvasNC.addEventListener('mouseup',stop); sigCanvasNC.addEventListener('mouseleave',stop);
  sigCanvasNC.addEventListener('touchstart',start,{passive:false}); sigCanvasNC.addEventListener('touchmove',move,{passive:false});
  sigCanvasNC.addEventListener('touchend',stop,{passive:false});
}

function clearSigNC() {
  if (!sigCtxNC||!sigCanvasNC) return;
  sigCtxNC.clearRect(0,0,sigCanvasNC.width,sigCanvasNC.height); hasSigNC=false;
}

// V113-SEV — Classification automatique de la gravité d'une non-conformité.
// Référentiels officiels :
//   • Règlement CE 852/2004 (hygiène denrées alimentaires)
//   • Règlement CE 853/2004 (denrées d'origine animale)
//   • Arrêté 21/12/2009 (températures réglementaires)
//   • Arrêté 29/09/1997 (plat témoin restauration collective)
//   • Règlement UE 1169/2011 (allergènes)
//   • Grille DGAL/DDPP — équivalences : Critique=classe D, Majeure=classe C, Mineure=classe B.
function classerGraviteNC(label, module, statut) {
  var l = (label || '').toString().toLowerCase();
  var m = (module || '').toString().toLowerCase();
  var s = (statut || '').toString().toLowerCase();

  // Si le libellé contient déjà "critique" (NC auto remontée d'un seuil HACCP)
  if (l.indexOf('critique') > -1 || s.indexOf('critique') > -1) return 'Critique';

  // ═══ CRITIQUE — danger immédiat pour la santé (classe D DDPP) ═══

  // Cuisson insuffisante (volaille 74°C, haché 70°C, porc/poisson 63°C)
  if (m.indexOf('cuisson') > -1 || l.indexOf('cuisson') > -1 || l.indexOf('cuit') > -1) {
    if (l.indexOf('volaille') > -1 || l.indexOf('hach') > -1 || l.indexOf('viande') > -1
        || l.indexOf('boeuf') > -1 || l.indexOf('bœuf') > -1
        || l.indexOf('porc') > -1 || l.indexOf('poisson') > -1
        || l.indexOf('t°') > -1 || l.indexOf('coeur') > -1 || l.indexOf('cœur') > -1
        || l.indexOf('cuisson') > -1) return 'Critique';
  }

  // Distribution / liaison (chaud < 63°C, froid > 10°C)
  if ((l.indexOf('distribution') > -1 || l.indexOf('liaison') > -1 || l.indexOf('service') > -1 || l.indexOf('remise') > -1)
      && (l.indexOf('chaud') > -1 || l.indexOf('froid') > -1 || l.indexOf('t°') > -1)) return 'Critique';

  // Refroidissement raté
  if (m.indexOf('refroi') > -1 || l.indexOf('refroidissement') > -1) return 'Critique';

  // Nuisibles présents
  if ((m.indexOf('nuisible') > -1 || l.indexOf('nuisible') > -1)
      && (s.indexOf('présence') > -1 || s.indexOf('presence') > -1
          || s.indexOf('détect') > -1 || s.indexOf('detect') > -1)) return 'Critique';

  // Maladie gastro / éviction
  if (l.indexOf('gastro') > -1 || l.indexOf('éviction') > -1 || l.indexOf('eviction') > -1
      || l.indexOf('maladie') > -1) return 'Critique';

  // DLC dépassée / produit périmé
  if (l.indexOf('dlc') > -1 && (l.indexOf('dépass') > -1 || l.indexOf('depass') > -1)) return 'Critique';
  if (l.indexOf('périmé') > -1 && (l.indexOf('produit') > -1 || l.indexOf('denrée') > -1 || l.indexOf('denree') > -1)) return 'Critique';

  // Plat témoin absent (arrêté 29/09/1997)
  if ((l.indexOf('plat témoin') > -1 || l.indexOf('plat temoin') > -1)
      && (s.indexOf('absent') > -1 || s.indexOf('manquant') > -1)) return 'Critique';

  // Eau non potable
  if (l.indexOf('eau') > -1 && (l.indexOf('non potable') > -1 || l.indexOf('contamin') > -1)) return 'Critique';

  // Congélateur > -15°C — frontière critique selon DDPP
  if ((l.indexOf('congél') > -1 || l.indexOf('congel') > -1) && l.indexOf('seuil -18') > -1) {
    // Si le seuil affiché est -18, on ne peut pas connaître la valeur exacte ici, on classe Majeure par défaut
    // sauf si le label précise une rupture franche
    if (l.indexOf('rupture') > -1 || l.indexOf('-10') > -1 || l.indexOf('-12') > -1) return 'Critique';
  }

  // Frigo / chambre froide positive > 8°C
  if ((l.indexOf('frigo') > -1 || l.indexOf('chambre froide') > -1)
      && (l.indexOf('rupture') > -1 || l.indexOf('+10') > -1 || l.indexOf('+12') > -1)) return 'Critique';

  // ═══ MAJEURE — risque sérieux sans danger immédiat (classe C DDPP) ═══

  // Huile friture (TPM > 25%, T° > 175°C)
  if (m.indexOf('huile') > -1 || l.indexOf('tpm') > -1 || l.indexOf('friteuse') > -1
      || (l.indexOf('huile') > -1)) return 'Majeure';

  // Températures enceintes — dépassement standard
  if (m.indexOf('températ') > -1 || m.indexOf('temperat') > -1
      || l.indexOf('frigo') > -1 || l.indexOf('chambre froide') > -1
      || l.indexOf('congél') > -1 || l.indexOf('congel') > -1
      || l.indexOf('cellule') > -1 || l.indexOf('vitrine') > -1) return 'Majeure';

  // Hygiène personnel (tenue, bijoux, blessure, lavage)
  if (m.indexOf('hygiène') > -1 || m.indexOf('hygiene') > -1
      || l.indexOf('tenue') > -1 || l.indexOf('bijou') > -1
      || l.indexOf('blessure') > -1 || l.indexOf('lavage') > -1
      || l.indexOf('mains') > -1) return 'Majeure';

  // Allergènes (règlement INCO 1169/2011)
  if (l.indexOf('allergène') > -1 || l.indexOf('allergene') > -1) return 'Majeure';

  // Réception — emballage abîmé non refusé
  if ((m.indexOf('réception') > -1 || m.indexOf('reception') > -1)
      && (l.indexOf('emballage') > -1 || l.indexOf('état') > -1 || l.indexOf('etat') > -1
          || l.indexOf('embal') > -1)) return 'Majeure';

  // Plan de nettoyage / désinfection
  if (m.indexOf('nettoyage') > -1 || l.indexOf('nettoyage') > -1
      || l.indexOf('désinfection') > -1 || l.indexOf('desinfection') > -1
      || l.indexOf('produit') > -1 && l.indexOf('contact') > -1) return 'Majeure';

  // Traçabilité défaillante
  if (l.indexOf('traçab') > -1 || l.indexOf('tracab') > -1
      || l.indexOf('n° lot') > -1 || l.indexOf('lot') > -1
      || l.indexOf('fournisseur') > -1 || l.indexOf('7 mentions') > -1) return 'Majeure';

  // Affichage obligatoire complet manquant
  if ((m.indexOf('affichage') > -1 || l.indexOf('affichage') > -1)
      && (l.indexOf('origine') > -1 || l.indexOf('viande') > -1
          || l.indexOf('fumer') > -1 || l.indexOf('vapot') > -1
          || l.indexOf('mineurs') > -1 || l.indexOf('alcool') > -1
          || l.indexOf('prix') > -1)) return 'Majeure';

  // Document obligatoire expiré
  if ((m.indexOf('document') > -1 || l.indexOf('document') > -1
       || l.indexOf('agrément') > -1 || l.indexOf('agrement') > -1
       || l.indexOf('attestation') > -1 || l.indexOf('cerfa') > -1)
      && (l.indexOf('expir') > -1 || l.indexOf('périmé') > -1 || l.indexOf('perime') > -1
          || s.indexOf('manquant') > -1 || s.indexOf('absent') > -1)) return 'Majeure';

  // Traces de nuisibles (sans bête vue)
  if ((m.indexOf('nuisible') > -1 || l.indexOf('nuisible') > -1)
      && (l.indexOf('trace') > -1 || l.indexOf('indice') > -1)) return 'Majeure';

  // Plat témoin présent mais grammage/T° hors seuil (hors absence déjà critique)
  if (l.indexOf('plat témoin') > -1 || l.indexOf('plat temoin') > -1) return 'Majeure';

  // Déchets / biodéchets (loi AGEC janvier 2024)
  if (m.indexOf('déchet') > -1 || m.indexOf('dechet') > -1
      || l.indexOf('biodéchet') > -1 || l.indexOf('biodechet') > -1
      || l.indexOf('agec') > -1) return 'Majeure';

  // Don association sans bordereau
  if (l.indexOf('don') > -1 && (l.indexOf('association') > -1 || l.indexOf('bordereau') > -1)) return 'Majeure';

  // Formation HACCP
  if (l.indexOf('formation') > -1 || l.indexOf('haccp 14h') > -1) return 'Majeure';

  // Pertes / invendus (récurrence)
  if (m.indexOf('pertes') > -1 || m.indexOf('invendus') > -1) return 'Majeure';

  // ═══ MINEURE — oubli administratif ou petit écart (classe B DDPP) ═══
  // Cas par défaut : signature manquante, étiquetage interne, document à renouveler < 30j,
  // affichage incomplet (1 mention), documentation accessoire.
  return 'Mineure';
}

function collectNCGlobales() {
  var ncs = [];
  var timestamp = getNowStr();

  // ── 1. Toutes les nc-auto visibles (tous modules) ──
  document.querySelectorAll('.nc-auto').forEach(function(el) {
    var visible = el.style.display === 'flex' || el.style.display === 'block' || el.classList.contains('visible');
    if (!visible) return;
    var module = 'Module inconnu';
    var page = el.closest('.page');
    if (page) {
      var h = page.querySelector('.mod-header-title');
      module = h ? h.textContent.trim() : page.id.replace('page-', '');
    }
    var desc = el.textContent.replace(/[⚡️]/g, '').trim();
    if (desc && !ncs.find(function(n){ return n.desc === desc && n.module === module; })) {
      // V113-SEV — Classification via classerGraviteNC (réf. DGAL/DDPP, CE 852/2004)
      ncs.push({ module: module, desc: desc, gravite: classerGraviteNC(desc, module, 'Non conforme'), heure: timestamp, source: 'auto' });
    }
  });

  // ── 2. Tous les boutons active-bad (Non conforme) dans tous les modules ──
  var modulePages = ['page-reception','page-temperatures','page-hygiene','page-ouverture',
    'page-cuisson','page-refroidissement','page-huiles','page-etiquetage','page-fermeture',
    'page-pertes','page-dechets','page-nuisibles','page-documents','page-affichage','page-audits'];

  modulePages.forEach(function(pageId) {
    var page = document.getElementById(pageId);
    if (!page) return;
    var h = page.querySelector('.mod-header-title');
    var moduleName = h ? h.textContent.trim() : pageId.replace('page-','');

    // Boutons active-bad dans les status-group
    page.querySelectorAll('.status-group').forEach(function(grp) {
      var badBtn = grp.querySelector('.status-btn.active-bad');
      if (!badBtn) return;
      // V111 — Exclure les status-group internes du registre NC (cartes "Statut clôture (X)")
      // pour casser la boucle d'auto-multiplication des NC
      if (grp.closest && grp.closest('[id^="nc_item_"]')) return;
      // Trouver le label de ce contrôle
      var row = grp.closest('.frow');
      var label = '';
      if (row) {
        var lbl = row.querySelector('.flabel');
        label = lbl ? lbl.textContent.trim().replace(/[*🔴⚡]/g,'').trim() : '';
      }
      if (!label) label = badBtn.textContent.replace(/[✗✘]/g,'').trim().substring(0,50);
      var desc = 'Non conforme : ' + label;
      if (!ncs.find(function(n){ return n.desc === desc && n.module === moduleName; })) {
        // Trouver l'action corrective associée si elle existe
        var actionDesc = '';
        var nextEl = grp.closest('.frow') ? grp.closest('.frow').nextElementSibling : null;
        while (nextEl) {
          if (nextEl.classList.contains('nc-action') && nextEl.classList.contains('visible')) {
            var actSel = nextEl.querySelector('select');
            var actDet = nextEl.querySelector('input[type=text]');
            var actResp = nextEl.querySelector('input[placeholder*="prenom"],input[placeholder*="Nom"]');
            if (actSel && actSel.value) actionDesc += actSel.options[actSel.selectedIndex].text;
            if (actDet && actDet.value) actionDesc += (actionDesc ? ' — ' : '') + actDet.value;
            if (actResp && actResp.value) actionDesc += ' (' + actResp.value + ')';
            break;
          }
          if (nextEl.classList.contains('fblock') || nextEl.classList.contains('frow') && !nextEl.classList.contains('nc-action')) break;
          nextEl = nextEl.nextElementSibling;
        }
        ncs.push({
          module: moduleName,
          desc: desc,
          gravite: classerGraviteNC(label || desc, moduleName, 'Non conforme'),
          heure: timestamp,
          source: 'controle',
          action: actionDesc || ''
        });
      }
    });

    // Badges de conformité hors seuil (températures, TPM...)
    page.querySelectorAll('.conformite-badge').forEach(function(badge) {
      if (!badge.classList.contains('nc') && !badge.classList.contains('bad')) return;
      var block = badge.closest('[id^="enc_block_"],[id^="friteuse_"],[id^="plat_"],[id^="refroi_"]');
      var blockLabel = block ? (block.querySelector('.fblock-title span') || block.querySelector('.fblock-title') || {textContent:''}).textContent.trim() : '';
      var desc = 'Hors seuil : ' + (blockLabel || badge.textContent.trim().substring(0,60));
      if (!ncs.find(function(n){ return n.desc === desc && n.module === moduleName; })) {
        ncs.push({ module: moduleName, desc: desc, gravite: 'Critique', heure: timestamp, source: 'seuil' });
      }
    });
  });

  // ── 3. V110 — Source localStorage : NC issues des données sauvegardées ──
  // Lit les statuts "Non conforme" stockés pour chaque module sur les 30 derniers jours.
  // Permet d'afficher les NC même quand les pages-modules ne sont pas ouvertes (dashboard, Pack DDPP).
  try {
    var _etabIdNC = (typeof ETAB_ID !== 'undefined' && ETAB_ID) ? ETAB_ID : (lsGet('haccp_etab_id') || 'local');
    var _modulesNC = ['page-reception','page-temperatures','page-hygiene','page-ouverture',
      'page-cuisson','page-refroidissement','page-huiles','page-etiquetage','page-fermeture',
      'page-pertes','page-dechets','page-nuisibles','page-documents','page-affichage','page-audits',
      'page-plat-temoin','page-liaison-thermique','page-registre-convives','page-analyses-micro'];
    var _limite30j = Date.now() - 30*86400000;
    _modulesNC.forEach(function(pid) {
      var key = 'haccp_module_data_' + pid + '_' + _etabIdNC;
      var stored = [];
      try { stored = JSON.parse(lsGet(key) || '[]'); } catch(e) { return; }
      stored.forEach(function(entry) {
        if (!entry || !entry.data) return;
        var entryDate = entry.timestamp ? new Date(entry.timestamp).getTime() : 0;
        if (entryDate < _limite30j) return;
        var modName = entry.data.module || pid.replace('page-','');
        var dateStr = entry.timestamp ? new Date(entry.timestamp).toLocaleString('fr-FR') : '';
        var signe = entry.data.signe || '';
        var statuts = entry.data.statuts || [];
        statuts.forEach(function(st) {
          if (!st || !st.statut) return;
          if (st.statut === 'Non conforme' || st.statut === 'Non respecté' || st.statut === 'Non effectué' || st.statut === 'Manquante' || st.statut === 'Manquant' || st.statut === 'Absent' || st.statut === 'Absente') {
            var desc = 'Non conforme : ' + (st.label || 'Contrôle');
            var sig = modName + '|' + desc + '|' + dateStr;
            if (!ncs.find(function(n){ return (n._sig || '') === sig; })) {
              // V112 — Reconstruire l'action corrective depuis st.action (mapping fiable
              // établi côté sauvegarde dans collectPageDataUniversel). Évite les inversions
              // par matching textuel et résout le bug "NC sans action" sur 7 modules.
              var actionStr = '';
              if (st.action) {
                var aT = st.action.type || '';
                var aD = st.action.detail || '';
                var aR = st.action.responsable || '';
                var aH = st.action.heure || '';
                actionStr = aT;
                if (aD) actionStr += (actionStr ? ' — ' : '') + aD;
                if (aR) actionStr += (actionStr ? ' (' + aR : '(' + aR);
                if (aH) actionStr += (aR ? ' à ' + aH + ')' : aH + ')');
                else if (aR) actionStr += ')';
              }
              ncs.push({
                module: modName,
                desc: desc,
                gravite: classerGraviteNC(st.label || desc, modName, st.statut),
                heure: dateStr,
                source: 'storage',
                signataire: signe,
                action: actionStr,
                _sig: sig
              });
            }
          }
        });
      });
    });
  } catch(eStor) { console.warn('collectNCGlobales — source localStorage erreur:', eStor.message || eStor); }

  return ncs;
}

function alimenterRegistreNC() {
  var ncs = collectNCGlobales();
  var container = document.getElementById('ncContainer');
  if (!container) return;

  // Supprimer les NC auto existantes (garder les manuelles)
  container.querySelectorAll('[data-source="auto"],[data-source="controle"],[data-source="seuil"]').forEach(function(el) {
    el.remove();
  });

  // Mettre à jour les compteurs
  var crit = ncs.filter(function(n){ return n.gravite === 'Critique'; }).length;
  var maj = ncs.filter(function(n){ return n.gravite === 'Majeure'; }).length;
  var min = ncs.filter(function(n){ return n.gravite === 'Mineure'; }).length;
  var critEl = document.getElementById('nc_count_crit');
  var majEl = document.getElementById('nc_count_maj');
  var minEl = document.getElementById('nc_count_min');
  if (critEl) critEl.textContent = crit;
  if (majEl) majEl.textContent = maj;
  if (minEl) minEl.textContent = min;

  if (ncs.length === 0) {
    var emptyDiv = document.createElement('div');
    emptyDiv.setAttribute('data-source','auto');
    emptyDiv.style.cssText = 'background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:14px 16px;margin-bottom:12px;font-size:13px;color:#15803d;font-weight:600;text-align:center';
    emptyDiv.textContent = '✅ Aucune non-conformité détectée sur les modules ouverts';
    container.insertBefore(emptyDiv, container.firstChild);
    return;
  }

  // Créer une carte NC pour chaque NC détectée
  ncs.forEach(function(nc, i) {
    ncCount++;
    var id = 'auto_' + Date.now() + '_' + i;
    var div = document.createElement('div');
    div.className = 'fblock';
    div.id = 'nc_item_' + id;
    div.setAttribute('data-source', nc.source || 'auto');
    div.style.borderLeft = '4px solid ' + (nc.gravite === 'Critique' ? '#dc2626' : nc.gravite === 'Majeure' ? '#f97316' : '#f59e0b');

    var graviteColor = nc.gravite === 'Critique' ? '#dc2626' : nc.gravite === 'Majeure' ? '#f97316' : '#f59e0b';
    var graviteBg = nc.gravite === 'Critique' ? '#fff8f8' : nc.gravite === 'Majeure' ? '#fff7ed' : '#fffbeb';

    div.innerHTML =
      '<div class="fblock-title" style="color:' + graviteColor + '">' +
        '<span>⚠️ NC — ' + nc.module + '</span>' +
        '<span style="font-size:10px;background:' + graviteColor + ';color:white;padding:2px 8px;border-radius:20px;margin-left:8px">' + nc.gravite + '</span>' +
      '</div>' +
      '<div style="background:' + graviteBg + ';border-radius:8px;padding:8px 12px;margin-bottom:10px">' +
        '<div style="font-size:11px;color:#6b7280;margin-bottom:2px">' + nc.heure + ' — ' + nc.module + '</div>' +
        '<div style="font-size:13px;font-weight:700;color:' + graviteColor + '">' + nc.desc + '</div>' +
      '</div>' +
      '<div class="frow"><div class="flabel req" style="color:#dc2626">Action corrective</div>' +
        '<input type="text" id="nc_action_' + id + '" class="finput" placeholder="Decrivez action corrective..." value="' + (nc.action||'').replace(/"/g,"'") + '"/>' +
      '</div>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">' +
        '<div class="frow"><div class="flabel">Responsable</div><input type="text" id="nc_resp_' + id + '" class="finput" placeholder="Nom & prenom"/></div>' +
        '<div class="frow"><div class="flabel">Date cloture</div><input type="date" id="nc_date_' + id + '" class="finput"/></div>' +
      '</div>' +
      '<div class="frow"><div class="flabel">Statut clôture (' + nc.module + ')</div>' +
        '<div class="status-group">' +
          '<button class="status-btn" data-shtype="ok" onclick="selHygBtn(this)">Cloturee</button>' +
          '<button class="status-btn" data-shtype="warn" onclick="selHygBtn(this)">En cours</button>' +
          '<button class="status-btn active-bad" data-shtype="bad" onclick="selHygBtn(this)">Ouverte</button>' +
        '</div>' +
      '</div>';

    container.insertBefore(div, container.firstChild);
  });
}

async function validerNC() {
  var prenom = document.getElementById('nc_sig_prenom').value.trim();
  var nom = document.getElementById('nc_sig_nom').value.trim();
  var reqEl = document.getElementById('nc_sig_required');
  if (!hasSigNC || !prenom || !nom) { reqEl.style.display='flex'; reqEl.scrollIntoView({behavior:'smooth',block:'center'}); return; }
  reqEl.style.display = 'none';
  alimenterRegistreNC();
  var ncsAuto = collectNCGlobales();
  // V113 — D : Sauvegarde Supabase AVANT PDF (awaited, après check signature)
  if (SB_READY && ETAB_ID) {
    try {
      await sbSauvegarderModule('nc', {secteur:SECTEUR_ACTIF, etab:ETAB.nom, ncs:ncsAuto, timestamp:new Date().toISOString()}, prenom+' '+nom);
    } catch(eSB) { console.warn('Supabase save error (nc):', eSB); }
  }
  ncGlobalesData = ncsAuto;
  document.getElementById('modalNCPdf').classList.add('visible');
  sauvegarderHistorique('NC & Actions correctives', prenom);
  sauvegarderDonnesModule('page-nc');
  stopBrouillonAuto(); effacerBrouillon('page-nc');
}

var ncGlobalesData = [];


function downloadNCPDF() {
  imprimerModule('page-nc', 'NC & Actions Correctives');
}
function confirmerSansNCPDF() { showConfirm('⚠️', 'NC — sans PDF', 'Sans PDF vous n\'avez pas de preuve legale. Continuez seulement si vous imprimez ce document.', 'Continuer quand même', '', function(ok){ if(ok) fermerModalNC(); }); }
function fermerModalNC() { document.getElementById('modalNCPdf').classList.remove('visible'); showPage('page-guide'); }

// ══════════════════════════════
// MODULE 14 — AFFICHAGE RÉGLEMENTAIRE
// ══════════════════════════════
var sigCanvasAff, sigCtxAff, isDrawingAff = false, hasSigAff = false;

function initSigAff() {
  sigCanvasAff = document.getElementById('sigCanvasAff');
  if (!sigCanvasAff) return;
  sigCtxAff = sigCanvasAff.getContext('2d');
  hasSigAff=false; isDrawingAff=false;
  var dpr=window.devicePixelRatio||1, w=sigCanvasAff.parentElement.clientWidth||340;
  sigCanvasAff.width=Math.round(w*dpr); sigCanvasAff.height=Math.round(140*dpr);
  sigCanvasAff.style.width=w+'px'; sigCanvasAff.style.height='140px';
  sigCtxAff.scale(dpr,dpr); sigCtxAff.strokeStyle='#1a1a2e';
  sigCtxAff.lineWidth=2.5; sigCtxAff.lineCap='round'; sigCtxAff.lineJoin='round';
  function pos(e){var r=sigCanvasAff.getBoundingClientRect();var s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top};}
  function start(e){e.preventDefault();isDrawingAff=true;var p=pos(e);sigCtxAff.beginPath();sigCtxAff.moveTo(p.x,p.y);}
  function move(e){e.preventDefault();if(!isDrawingAff)return;var p=pos(e);sigCtxAff.lineTo(p.x,p.y);sigCtxAff.stroke();hasSigAff=true;}
  function stop(e){e.preventDefault();isDrawingAff=false;}
  sigCanvasAff.addEventListener('mousedown',start); sigCanvasAff.addEventListener('mousemove',move);
  sigCanvasAff.addEventListener('mouseup',stop); sigCanvasAff.addEventListener('mouseleave',stop);
  sigCanvasAff.addEventListener('touchstart',start,{passive:false}); sigCanvasAff.addEventListener('touchmove',move,{passive:false});
  sigCanvasAff.addEventListener('touchend',stop,{passive:false});
}

