function ptCalculerDestruction() {
  var dateEl = document.getElementById('pt_date_repas');
  var heureEl = document.getElementById('pt_heure_repas');
  var affEl = document.getElementById('pt_destruction_auto');
  if (!dateEl || !dateEl.value || !heureEl || !heureEl.value) return;
  var dt = new Date(dateEl.value + 'T' + heureEl.value);
  dt.setHours(dt.getHours() + 72);
  var options = { weekday:'long', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' };
  var dateStr = dt.toLocaleDateString('fr-FR', options);
  if (affEl) {
    affEl.textContent = '🗑️ Destruction obligatoire avant le : ' + dateStr;
    affEl.style.background = '#dcfce7';
    affEl.style.color = '#15803d';
  }
}

