function ltAjouterPlat(type) {
  var isChaud = type === 'chaud';
  if (isChaud) ltChaudCount++; else ltFroidCount++;
  var id = type + '_' + (isChaud ? ltChaudCount : ltFroidCount);
  var container = document.getElementById(isChaud ? 'ltChaudsContainer' : 'ltFroidsContainer');
  var seuil = isChaud ? 63 : 10;
  var couleur = isChaud ? '#dc2626' : '#0284c7';
  var seuilTexte = isChaud ? '≥ +63°C' : '≤ +10°C';
  var div = document.createElement('div');
  div.className = 'fblock';
  div.id = 'lt_plat_' + id;
  div.style.borderLeft = '4px solid ' + couleur;
  div.style.marginBottom = '10px';
  div.innerHTML =
    '<div class="fblock-title" style="color:' + couleur + '">' + (isChaud ? '🔥' : '❄️') + ' Plat ' + (isChaud ? ltChaudCount : ltFroidCount) + '</div>' +
    '<div class="frow"><div class="flabel req">Nom du plat</div><input class="finput" id="lt_nom_' + id + '" placeholder="Ex: Rôti de porc..."/></div>' +
    '<div class="frow"><div class="flabel">T° à la production</div><input class="finput" type="number" id="lt_tprod_' + id + '" placeholder="°C" step="0.1"/></div>' +
    '<div class="frow"><div class="flabel">T° à la distribution</div><input class="finput" type="number" id="lt_tdist_' + id + '" placeholder="°C" step="0.1"/></div>' +
    '<div id="lt_nc_' + id + '" class="nc-auto" style="display:none;background:#fee2e2;color:#dc2626;padding:6px 10px;border-radius:6px;font-size:12px;font-weight:700;margin-top:4px">⚡ NC — Seuil ' + seuilTexte + ' non respecté</div>' +
    '<div style="font-size:11px;color:' + couleur + ';font-weight:600;margin-top:4px">🌡️ Seuil réglementaire : ' + seuilTexte + '</div>';
  container.appendChild(div);
  var tdistEl = document.getElementById('lt_tdist_' + id);
  var ncEl = document.getElementById('lt_nc_' + id);
  if (tdistEl && ncEl) {
    (function(el, nc, s, ch) {
      el.addEventListener('change', function() {
        var v = parseFloat(el.value);
        nc.style.display = (!isNaN(v) && (ch ? v < s : v > s)) ? 'block' : 'none';
      });
    })(tdistEl, ncEl, seuil, isChaud);
  }
}

