function _testLog(msg, color) {
  var el = document.getElementById('testStatusMsg');
  if (el) {
    el.style.display = 'block';
    el.style.color = color || '#15803d';
    el.style.background = (color === '#dc2626') ? '#fef2f2' : (color === '#f59e0b' ? '#fffbeb' : '#f0fdf4');
    el.innerHTML = msg;
  }
}

// V85 — Initialise les variables minimales SANS rediriger ni appeler showPage
function _testEnsureConnected() {
  if (typeof ETAB_ID === 'undefined' || !ETAB_ID) {
    try { ETAB_ID = 'local-test'; } catch(e) {}
  }
  try { if (typeof MODE_LOCAL !== 'undefined') MODE_LOCAL = true; } catch(e) {}
  try { if (typeof CLIENT_MODE !== 'undefined') CLIENT_MODE = false; } catch(e) {}
  try {
    if (typeof ETAB === 'undefined' || !ETAB) { window.ETAB = {}; }
    if (!ETAB.nom) ETAB.nom = 'RESTAURANT TEST';
    if (!ETAB.secteur) ETAB.secteur = 'resto';
  } catch(e) {}
}

// Génère une session archivée pour un module donné
function _testCreerSession(pageId, sessionData, customTimestamp) {
  try {
    var key = 'haccp_module_data_' + pageId + '_' + (typeof ETAB_ID !== 'undefined' && ETAB_ID ? ETAB_ID : 'local');
    var ts = customTimestamp || new Date().toISOString();
    var entry = {
      pageId: pageId,
      timestamp: ts,
      data: sessionData
    };
    // Conserver le timestamp dans data aussi (pour l'affichage)
    if (sessionData && !sessionData.timestamp) sessionData.timestamp = ts;
    var stored = [];
    try { stored = JSON.parse(localStorage.getItem(key) || '[]'); } catch(e) {}
    stored.unshift(entry);
    // V86 — Limite augmentée à 200 pour 7 jours de tests
    if (stored.length > 200) stored = stored.slice(0, 200);
    localStorage.setItem(key, JSON.stringify(stored));
  } catch(e) { console.warn('test session err:', e); }
}

