    (function(){
      'use strict';

      // ── V96 : Récap tarif dynamique ──
      window.updateRecapTarif = function() {
        var formule = (document.getElementById('insc_formule') || {}).value;
        var engagement = (document.getElementById('insc_engagement') || {}).value;
        var recap = document.getElementById('recapTarif');
        if (!recap) return;
        if (!formule || !engagement) {
          recap.style.display = 'none';
          return;
        }
        var prix = 0, prixSans = 0, titre = '', cible = '';
        if (formule === 'essentiel') {
          titre = '🥉 Essentiel';
          cible = '1 établissement';
          prix = engagement === 'annuel' ? 39 : 59;
          prixSans = 59;
        } else if (formule === 'multisites') {
          titre = '🥇 Multi-sites';
          cible = 'Jusqu\'à 5 établissements';
          prix = engagement === 'annuel' ? 129 : 159;
          prixSans = 159;
        }
        var engLabel = engagement === 'annuel' ? 'Avec engagement 12 mois' : 'Sans engagement';
        var economie = engagement === 'annuel' ? ('💰 Économie : ' + ((prixSans - prix) * 12) + ' € / an') : '';
        var t = document.getElementById('recapTitle');
        var e = document.getElementById('recapEngagement');
        var p = document.getElementById('recapPrix');
        var ec = document.getElementById('recapEconomie');
        var b = document.getElementById('recapBonus');
        if (t) t.textContent = titre + ' — ' + cible;
        if (e) e.textContent = engLabel;
        if (p) p.textContent = prix + ' €';
        if (ec) ec.textContent = economie;
        if (b) b.style.display = engagement === 'annuel' ? 'block' : 'none';
        recap.style.display = 'block';
      };

      // ── Outils ──
      function showStatus(msg, type) {
        var el = document.getElementById('inscriptionStatus');
        if (!el) return;
        el.style.display = 'block';
        el.textContent = msg;
        if (type === 'ok') {
          el.style.background = 'rgba(74,222,128,0.12)';
          el.style.border = '1px solid rgba(74,222,128,0.3)';
          el.style.color = '#4ade80';
        } else if (type === 'err') {
          el.style.background = 'rgba(220,38,38,0.12)';
          el.style.border = '1px solid rgba(220,38,38,0.3)';
          el.style.color = '#fca5a5';
        } else {
          el.style.background = 'rgba(255,255,255,0.06)';
          el.style.border = '1px solid rgba(255,255,255,0.1)';
          el.style.color = 'rgba(255,255,255,0.85)';
        }
      }

      function genererCodeAcces() {
        // Format HACCP-XXXXX-2026
        var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // sans I, O, 0, 1 (confusion)
        var part = '';
        for (var i = 0; i < 5; i++) {
          part += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        var year = new Date().getFullYear();
        return 'HACCP-' + part + '-' + year;
      }

      function genererMotDePasse() {
        // 6 chiffres
        var pwd = '';
        for (var i = 0; i < 6; i++) {
          pwd += Math.floor(Math.random() * 10);
        }
        return pwd;
      }

      // ── Soumission formulaire inscription ──
      window.submitInscriptionHaccp = function(event) {
        event.preventDefault();
        var btn = document.getElementById('btnSubmitInscription');
        if (btn) { btn.disabled = true; btn.textContent = '⏳ Envoi en cours…'; }

        var data = {
          etablissement: (document.getElementById('insc_etab') || {}).value || '',
          secteur: (document.getElementById('insc_secteur') || {}).value || '',
          nb_repas_jour: parseInt((document.getElementById('insc_repas') || {}).value || '0', 10) || null,
          responsable: (document.getElementById('insc_resp') || {}).value || '',
          email: (document.getElementById('insc_email') || {}).value || '',
          telephone: (document.getElementById('insc_tel') || {}).value || '',
          formule: (document.getElementById('insc_formule') || {}).value || '',
          engagement: (document.getElementById('insc_engagement') || {}).value || '',
          adresse: (document.getElementById('insc_adresse') || {}).value || '',
          siret: (document.getElementById('insc_siret') || {}).value || '',
          message: (document.getElementById('insc_message') || {}).value || '',
          statut: 'en_attente'
        };

        if (!window._supabase) {
          showStatus('❌ Erreur : connexion à la base impossible. Réessayez.', 'err');
          if (btn) { btn.disabled = false; btn.textContent = '🚀 Envoyer ma demande'; }
          return false;
        }

        // Insertion Supabase
        window._supabase.from('demandes_inscription').insert([data]).then(function(res) {
          if (res.error) {
            console.error('[V95] Erreur Supabase insert:', res.error);
            showStatus('❌ Erreur lors de l\'envoi : ' + (res.error.message || 'inconnue'), 'err');
            if (btn) { btn.disabled = false; btn.textContent = '🚀 Envoyer ma demande'; }
            return;
          }

          // Notification email à l'admin (best-effort, ne bloque pas si EmailJS pas configuré)
          if (window.emailjs && window.HACCP_CONFIG.EMAILJS_PUBLIC_KEY && window.HACCP_CONFIG.EMAILJS_TEMPLATE_ADMIN) {
            try {
              window.emailjs.send(
                window.HACCP_CONFIG.EMAILJS_SERVICE,
                window.HACCP_CONFIG.EMAILJS_TEMPLATE_ADMIN,
                {
                  to_email: window.HACCP_CONFIG.ADMIN_EMAIL,
                  etablissement: data.etablissement,
                  secteur: data.secteur,
                  responsable: data.responsable,
                  email_client: data.email,
                  telephone: data.telephone,
                  formule: data.formule,
                  engagement: data.engagement,
                  nb_repas: data.nb_repas_jour || '?',
                  message: data.message || '(aucun)'
                }
              );
            } catch(e) { console.warn('[V95] EmailJS admin échec:', e); }
          }

          showStatus('✅ Demande envoyée ! Vous recevrez votre code d\'accès par email après validation (sous 24h ouvrées).', 'ok');
          var form = document.getElementById('formInscriptionHaccp');
          if (form) form.reset();
          if (btn) { btn.disabled = false; btn.textContent = '🚀 Envoyer ma demande'; }
        }).catch(function(err) {
          console.error('[V95] Catch Supabase:', err);
          showStatus('❌ Erreur réseau. Vérifiez votre connexion.', 'err');
          if (btn) { btn.disabled = false; btn.textContent = '🚀 Envoyer ma demande'; }
        });

        return false;
      };

      // ── ADMIN ──
      var adminCurrentTab = 'demandes';

      window.loginAdmin = function() {
        var pwd = (document.getElementById('adminPwd') || {}).value || '';
        var err = document.getElementById('adminLoginErr');
        if (pwd === window.HACCP_CONFIG.ADMIN_PASSWORD) {
          var box = document.getElementById('adminLoginBox');
          var dash = document.getElementById('adminDashboard');
          if (box) box.style.display = 'none';
          if (dash) dash.style.display = 'block';
          adminTab('demandes');
        } else {
          if (err) {
            err.style.display = 'block';
            err.textContent = 'Mot de passe incorrect';
          }
        }
      };

      window.logoutAdmin = function() {
        var box = document.getElementById('adminLoginBox');
        var dash = document.getElementById('adminDashboard');
        var pwd = document.getElementById('adminPwd');
        if (box) box.style.display = 'block';
        if (dash) dash.style.display = 'none';
        if (pwd) pwd.value = '';
        showPage('page-presentation');
      };

      window.adminTab = function(tab) {
        adminCurrentTab = tab;
        // Mise à jour visuelle des onglets
        ['demandes', 'clients', 'historique'].forEach(function(t) {
          var btn = document.getElementById('tab' + t.charAt(0).toUpperCase() + t.slice(1));
          if (btn) {
            if (t === tab) {
              btn.style.background = 'rgba(74,222,128,0.15)';
              btn.style.color = '#4ade80';
            } else {
              btn.style.background = 'transparent';
              btn.style.color = 'rgba(255,255,255,0.7)';
            }
          }
        });
        if (tab === 'demandes') loadAdminDemandes();
        else if (tab === 'clients') loadAdminClients();
        else if (tab === 'historique') loadAdminHistorique();
      };

      function escapeHtml(s) {
        return String(s || '').replace(/[&<>"']/g, function(c) {
          return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
        });
      }

      function loadAdminDemandes() {
        var c = document.getElementById('adminContent');
        if (!c || !window._supabase) { return; }
        c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Chargement…</div>';

        window._supabase.from('demandes_inscription').select('*').order('date_demande', { ascending: false }).then(function(res) {
          if (res.error) {
            c.innerHTML = '<div style="color:#fca5a5;padding:20px;text-align:center">Erreur: ' + escapeHtml(res.error.message) + '</div>';
            return;
          }
          var rows = res.data || [];
          var pending = rows.filter(function(r) { return r.statut === 'en_attente'; });
          var cnt = document.getElementById('cntDemandes');
          if (cnt) cnt.textContent = pending.length;

          if (rows.length === 0) {
            c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Aucune demande pour l\'instant.</div>';
            return;
          }

          var html = '';
          rows.forEach(function(r) {
            var statutColor = r.statut === 'en_attente' ? '#f59e0b' : (r.statut === 'validee' ? '#4ade80' : '#dc2626');
            var statutLabel = r.statut === 'en_attente' ? '⏳ EN ATTENTE' : (r.statut === 'validee' ? '✅ VALIDÉE' : '❌ REFUSÉE');
            var dateStr = new Date(r.date_demande).toLocaleString('fr-FR');

            html += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:14px;margin-bottom:10px">';
            html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px;margin-bottom:8px">';
            html += '<div><div style="font-size:14px;font-weight:800;color:white">' + escapeHtml(r.etablissement) + '</div><div style="font-size:11px;color:rgba(255,255,255,0.55)">' + dateStr + '</div></div>';
            html += '<div style="font-size:10px;font-weight:800;color:' + statutColor + '">' + statutLabel + '</div>';
            html += '</div>';
            html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;font-size:12px;color:rgba(255,255,255,0.75);margin-bottom:10px">';
            html += '<div>👤 ' + escapeHtml(r.responsable) + '</div>';
            html += '<div>📧 ' + escapeHtml(r.email) + '</div>';
            html += '<div>📞 ' + escapeHtml(r.telephone) + '</div>';
            html += '<div>🍽️ ' + escapeHtml(r.secteur) + (r.nb_repas_jour ? ' — ' + r.nb_repas_jour + ' repas/j' : '') + '</div>';
            html += '<div>💰 ' + escapeHtml(r.formule) + ' / ' + escapeHtml(r.engagement) + '</div>';
            if (r.code_genere) html += '<div style="color:#4ade80;font-weight:700">🔑 ' + escapeHtml(r.code_genere) + '</div>';
            html += '</div>';
            if (r.message) html += '<div style="font-size:11px;color:rgba(255,255,255,0.6);font-style:italic;padding:6px 10px;background:rgba(255,255,255,0.04);border-radius:6px;margin-bottom:10px">💬 ' + escapeHtml(r.message) + '</div>';
            if (r.statut === 'en_attente') {
              html += '<div style="display:flex;gap:8px;flex-wrap:wrap">';
              html += '<button onclick="validerDemande(\'' + r.id + '\')" style="background:linear-gradient(135deg,#4ade80,#22c55e);color:#0a0e1a;border:none;padding:8px 16px;border-radius:7px;font-weight:800;font-size:12px;cursor:pointer;font-family:Outfit,sans-serif">✅ Valider et envoyer code</button>';
              html += '<button onclick="refuserDemande(\'' + r.id + '\')" style="background:rgba(220,38,38,0.12);color:#fca5a5;border:1px solid rgba(220,38,38,0.3);padding:8px 16px;border-radius:7px;font-weight:700;font-size:12px;cursor:pointer;font-family:Outfit,sans-serif">❌ Refuser</button>';
              html += '</div>';
            }
            html += '</div>';
          });
          c.innerHTML = html;
        });
      }

      function loadAdminClients() {
        var c = document.getElementById('adminContent');
        if (!c || !window._supabase) return;
        c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Chargement…</div>';

        window._supabase.from('comptes_clients').select('*').order('date_debut', { ascending: false }).then(function(res) {
          if (res.error) { c.innerHTML = '<div style="color:#fca5a5;padding:20px">Erreur: ' + escapeHtml(res.error.message) + '</div>'; return; }
          var rows = res.data || [];
          var actifs = rows.filter(function(r) { return r.actif; });
          var cnt = document.getElementById('cntClients');
          if (cnt) cnt.textContent = actifs.length;

          if (rows.length === 0) {
            c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Aucun client pour l\'instant.</div>';
            return;
          }

          var html = '';
          rows.forEach(function(r) {
            var statutColor = r.actif ? '#4ade80' : '#dc2626';
            var statutLabel = r.actif ? '✅ ACTIF' : '⛔ DÉSACTIVÉ';
            var dateDebut = r.date_debut ? new Date(r.date_debut).toLocaleDateString('fr-FR') : '?';

            html += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:14px;margin-bottom:10px">';
            html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px;margin-bottom:8px">';
            html += '<div><div style="font-size:14px;font-weight:800;color:white">' + escapeHtml(r.etablissement) + '</div><div style="font-size:11px;color:#4ade80;font-weight:700">🔑 ' + escapeHtml(r.code_acces) + '</div></div>';
            html += '<div style="font-size:10px;font-weight:800;color:' + statutColor + '">' + statutLabel + '</div>';
            html += '</div>';
            html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;font-size:12px;color:rgba(255,255,255,0.75);margin-bottom:10px">';
            html += '<div>📧 ' + escapeHtml(r.email) + '</div>';
            html += '<div>💰 ' + escapeHtml(r.formule) + ' / ' + escapeHtml(r.engagement) + '</div>';
            html += '<div>📅 Depuis ' + dateDebut + '</div>';
            html += '</div>';
            if (r.actif) {
              html += '<button onclick="desactiverClient(\'' + r.id + '\',\'' + escapeHtml(r.code_acces) + '\')" style="background:rgba(220,38,38,0.15);color:#fca5a5;border:1px solid rgba(220,38,38,0.3);padding:8px 16px;border-radius:7px;font-weight:700;font-size:12px;cursor:pointer;font-family:Outfit,sans-serif">⛔ Désactiver</button>';
            } else {
              if (r.motif_desactivation) html += '<div style="font-size:11px;color:rgba(255,255,255,0.55);font-style:italic">Motif: ' + escapeHtml(r.motif_desactivation) + '</div>';
              html += '<button onclick="reactiverClient(\'' + r.id + '\',\'' + escapeHtml(r.code_acces) + '\')" style="background:rgba(74,222,128,0.12);color:#4ade80;border:1px solid rgba(74,222,128,0.3);padding:8px 16px;border-radius:7px;font-weight:700;font-size:12px;cursor:pointer;font-family:Outfit,sans-serif;margin-top:6px">✅ Réactiver</button>';
            }
            html += '</div>';
          });
          c.innerHTML = html;
        });
      }

      function loadAdminHistorique() {
        var c = document.getElementById('adminContent');
        if (!c || !window._supabase) return;
        c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Chargement…</div>';

        window._supabase.from('historique_admin').select('*').order('date_action', { ascending: false }).limit(100).then(function(res) {
          if (res.error) { c.innerHTML = '<div style="color:#fca5a5;padding:20px">Erreur: ' + escapeHtml(res.error.message) + '</div>'; return; }
          var rows = res.data || [];
          if (rows.length === 0) {
            c.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px">Aucune action enregistrée.</div>';
            return;
          }
          var html = '';
          rows.forEach(function(r) {
            var dateStr = new Date(r.date_action).toLocaleString('fr-FR');
            html += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:9px;padding:11px;margin-bottom:7px;font-size:12px">';
            html += '<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><span style="font-weight:700;color:white">' + escapeHtml(r.action) + '</span><span style="color:rgba(255,255,255,0.5);font-size:11px">' + dateStr + '</span></div>';
            if (r.code_concerne) html += '<div style="color:#4ade80;font-size:11px;margin-top:4px">🔑 ' + escapeHtml(r.code_concerne) + '</div>';
            if (r.motif) html += '<div style="color:rgba(255,255,255,0.6);font-size:11px;margin-top:4px;font-style:italic">' + escapeHtml(r.motif) + '</div>';
            html += '</div>';
          });
          c.innerHTML = html;
        });
      }

      // ── Actions admin ──
      window.validerDemande = function(id) {
        if (!window._supabase) return;
        if (!confirm('Valider cette demande ?\n\nUn code d\'accès sera généré et un email envoyé au client.')) return;

        // Récupérer la demande
        window._supabase.from('demandes_inscription').select('*').eq('id', id).single().then(function(res) {
          if (res.error || !res.data) { alert('Erreur: ' + (res.error && res.error.message)); return; }
          var d = res.data;
          var codeAcces = genererCodeAcces();
          var motDePasse = genererMotDePasse();
          var dateDebut = new Date().toISOString().slice(0, 10);

          // Créer compte client
          var compte = {
            code_acces: codeAcces,
            mot_de_passe: motDePasse,
            etablissement: d.etablissement,
            email: d.email,
            formule: d.formule,
            engagement: d.engagement,
            date_debut: dateDebut,
            actif: true,
            demande_id: d.id
          };

          window._supabase.from('comptes_clients').insert([compte]).then(function(ins) {
            if (ins.error) { alert('Erreur création compte: ' + ins.error.message); return; }

            // V100 : Créer aussi une ligne dans etablissements pour permettre la connexion
            var secteurMap = {
              'resto_trad': 'resto',
              'boulangerie': 'bp',
              'fast_food': 'rapide',
              'boucherie': 'resto',
              'collective': 'resto'
            };
            var secteurInterne = secteurMap[d.secteur] || 'resto';
            var etabRow = {
              code_acces: codeAcces,
              mot_de_passe: motDePasse,
              nom: d.etablissement,
              secteur: secteurInterne,
              adresse: d.adresse || '',
              siret: d.siret || '',
              actif: true
            };
            window._supabase.from('etablissements').insert([etabRow]).then(function(ie) {
              if (ie.error) { console.warn('[V100] Erreur insert etablissements (login impossible):', ie.error.message); }
              else { console.log('[V100] Etablissement créé pour connexion :', codeAcces); }
            });

            // Mettre à jour la demande
            window._supabase.from('demandes_inscription').update({
              statut: 'validee',
              code_genere: codeAcces,
              date_traitement: new Date().toISOString()
            }).eq('id', id).then(function() {

              // Historique
              window._supabase.from('historique_admin').insert([{
                action: 'Validation demande',
                code_concerne: codeAcces,
                motif: 'Validation pour ' + d.etablissement
              }]).then(function(){});

              // Email au client
              if (window.emailjs && window.HACCP_CONFIG.EMAILJS_PUBLIC_KEY && window.HACCP_CONFIG.EMAILJS_TEMPLATE_CLIENT) {
                try {
                  window.emailjs.send(
                    window.HACCP_CONFIG.EMAILJS_SERVICE,
                    window.HACCP_CONFIG.EMAILJS_TEMPLATE_CLIENT,
                    {
                      to_email: d.email,
                      etablissement: d.etablissement,
                      responsable: d.responsable,
                      code_acces: codeAcces,
                      mot_de_passe: motDePasse,
                      formule: d.formule
                    }
                  );
                } catch(e) { console.warn('Email client échec:', e); }
              }

              alert('✅ Validation réussie !\n\nCode généré : ' + codeAcces + '\nMot de passe : ' + motDePasse + '\n\nUn email est envoyé au client.');
              loadAdminDemandes();
            });
          });
        });
      };

      window.refuserDemande = function(id) {
        if (!window._supabase) return;
        var motif = prompt('Motif du refus (sera enregistré) :');
        if (motif === null) return;
        window._supabase.from('demandes_inscription').update({
          statut: 'refusee',
          date_traitement: new Date().toISOString()
        }).eq('id', id).then(function(res) {
          if (res.error) { alert('Erreur: ' + res.error.message); return; }
          window._supabase.from('historique_admin').insert([{
            action: 'Refus demande',
            motif: motif || '(aucun motif)'
          }]).then(function(){});
          loadAdminDemandes();
        });
      };

      window.desactiverClient = function(id, code) {
        if (!window._supabase) return;
        var motif = prompt('Motif de la désactivation :');
        if (motif === null) return;
        window._supabase.from('comptes_clients').update({
          actif: false,
          date_desactivation: new Date().toISOString(),
          motif_desactivation: motif || ''
        }).eq('id', id).then(function(res) {
          if (res.error) { alert('Erreur: ' + res.error.message); return; }
          // V100 : Désactiver aussi dans etablissements pour bloquer la connexion
          window._supabase.from('etablissements').update({ actif: false }).eq('code_acces', code).then(function(){});
          window._supabase.from('historique_admin').insert([{
            action: 'Désactivation client',
            code_concerne: code,
            motif: motif || ''
          }]).then(function(){});
          loadAdminClients();
        });
      };

      window.reactiverClient = function(id, code) {
        if (!window._supabase) return;
        if (!confirm('Réactiver le compte ' + code + ' ?')) return;
        window._supabase.from('comptes_clients').update({
          actif: true,
          date_desactivation: null,
          motif_desactivation: null
        }).eq('id', id).then(function(res) {
          if (res.error) { alert('Erreur: ' + res.error.message); return; }
          // V100 : Réactiver aussi dans etablissements
          window._supabase.from('etablissements').update({ actif: true }).eq('code_acces', code).then(function(){});
          window._supabase.from('historique_admin').insert([{
            action: 'Réactivation client',
            code_concerne: code
          }]).then(function(){});
          loadAdminClients();
        });
      };

      // ── V102 : Mise à jour bandeau du haut avec infos client ──
      window.updateTopbarEtab = function() {
        try {
          var nomEl = document.getElementById('topbarEtabNom');
          var subEl = document.getElementById('topbarEtabSub');
          if (!nomEl || !subEl) return;
          var etab = (typeof ETAB !== 'undefined' && ETAB) ? ETAB : {};
          if (etab.nom) nomEl.textContent = etab.nom;
          var sub = [];
          if (etab.adresse) sub.push(etab.adresse);
          if (etab.siret) sub.push('SIRET ' + etab.siret);
          if (sub.length > 0) {
            subEl.textContent = sub.join(' · ');
            subEl.style.display = 'block';
          } else {
            subEl.style.display = 'none';
          }
        } catch(e) { console.warn('[V102] updateTopbarEtab:', e); }
      };
      // Mise à jour automatique périodique (couvre les cas de session restaurée)
      setInterval(function(){
        try { if (window.updateTopbarEtab) window.updateTopbarEtab(); } catch(e){}
      }, 3000);

      // ── V102 : Injection footer SIRET + adresse sur tous les PDF générés ──
      // Cette fonction hook le print() pour ajouter automatiquement un footer
      // Mais on l'applique de manière non-intrusive : on injecte directement dans les zones d'impression
      window.getFooterEtabHTML = function() {
        try {
          var etab = (typeof ETAB !== 'undefined' && ETAB) ? ETAB : {};
          if (!etab.nom) return '';
          var lignes = ['<strong>' + (etab.nom || '') + '</strong>'];
          if (etab.adresse) lignes.push(etab.adresse);
          if (etab.siret) lignes.push('SIRET : ' + etab.siret);
          return '<div style="position:fixed;bottom:8px;left:0;right:0;text-align:center;font-size:9px;color:#666;font-family:Arial,sans-serif;line-height:1.4;padding:4px;border-top:1px solid #ddd" class="haccp-print-footer">' + lignes.join(' · ') + ' · Document généré le ' + new Date().toLocaleDateString('fr-FR') + ' à ' + new Date().toLocaleTimeString('fr-FR').slice(0,5) + '</div>';
        } catch(e) { return ''; }
      };

      // V103 : Hook window.print pour injecter le footer dans #printOverlay
      // Car @media print cache tout sauf #printOverlay (donc le footer ajouté au body est masqué)
      window.getFooterEtabHTMLForPrintOverlay = function() {
        try {
          var etab = (typeof ETAB !== 'undefined' && ETAB) ? ETAB : {};
          if (!etab.nom) return '';
          var parts = [];
          parts.push('<strong>' + etab.nom + '</strong>');
          if (etab.adresse) parts.push(etab.adresse);
          if (etab.siret) parts.push('SIRET : ' + etab.siret);
          parts.push('Document généré le ' + new Date().toLocaleDateString('fr-FR') + ' à ' + new Date().toLocaleTimeString('fr-FR').slice(0,5));
          return '<div class="haccp-print-footer-overlay" style="margin-top:24px;padding:10px 16px;border-top:1.5px solid #d1d5db;text-align:center;font-size:10px;color:#6b7280;font-family:Arial,sans-serif;line-height:1.5">' + parts.join(' · ') + '</div>';
        } catch(e) { return ''; }
      };

      // V104 : MutationObserver — détecte la création de #printOverlay dans le DOM
      // et y injecte automatiquement le footer dès qu'il apparaît.
      // Méthode garantie indépendante du hook window.print
      window.injectFooterInPrintOverlay = function(overlay) {
        try {
          if (!overlay) return;
          // Éviter doublons
          if (overlay.querySelector('.haccp-print-footer-overlay')) return;
          var footerHTML = window.getFooterEtabHTMLForPrintOverlay();
          if (!footerHTML) return;
          var tmp = document.createElement('div');
          tmp.innerHTML = footerHTML;
          var footer = tmp.firstChild;
          // Injecter avant le dernier élément (qui est souvent la barre de boutons "Imprimer/Fermer")
          // Mais sans toucher à cette barre — on l'insère juste avant
          var children = overlay.children;
          if (children.length > 1) {
            // Insérer avant le dernier enfant (généralement la barre boutons)
            overlay.insertBefore(footer, children[children.length - 1]);
          } else {
            overlay.appendChild(footer);
          }
          console.log('[V104] Footer injecté dans printOverlay');
        } catch(e) { console.warn('[V104] injectFooter:', e); }
      };

      // Observer toutes les additions au body pour détecter #printOverlay
      try {
        var v104Observer = new MutationObserver(function(mutations) {
          mutations.forEach(function(m) {
            m.addedNodes.forEach(function(node) {
              if (node.nodeType === 1 && node.id === 'printOverlay') {
                // Petit délai pour que tout le contenu soit injecté
                setTimeout(function(){ window.injectFooterInPrintOverlay(node); }, 50);
              }
            });
          });
        });
        v104Observer.observe(document.body, { childList: true });
        console.log('[V104] MutationObserver actif sur printOverlay');
      } catch(e) { console.warn('[V104] Observer:', e); }

      var _origPrint = window.print;
      window.print = function() {
        try {
          var overlay = document.getElementById('printOverlay');
          if (overlay) window.injectFooterInPrintOverlay(overlay);
        } catch(e) { console.warn('[V104] Hook print:', e); }
        return _origPrint.apply(window, arguments);
      };

      // Hook beforeprint pour injecter le footer dans le body
      window.addEventListener('beforeprint', function() {
        try {
          var existingFooter = document.querySelector('.haccp-print-footer');
          if (existingFooter) existingFooter.remove();
          var footerHTML = window.getFooterEtabHTML();
          if (footerHTML) {
            var div = document.createElement('div');
            div.innerHTML = footerHTML;
            document.body.appendChild(div.firstChild);
          }
        } catch(e) { console.warn('[V102] beforeprint footer:', e); }
      });
      window.addEventListener('afterprint', function() {
        try {
          var existingFooter = document.querySelector('.haccp-print-footer');
          if (existingFooter) existingFooter.remove();
        } catch(e){}
      });

      // ── Détection mode admin via URL ──
      function checkAdminUrl() {
        try {
          var params = new URLSearchParams(window.location.search);
          if (params.get('admin') === 'true') {
            setTimeout(function(){
              if (typeof showPage === 'function') showPage('page-admin');
            }, 200);
          }
        } catch(e) {}
      }

      // ── Cacher topbar (bandeau "Restaurant Le Marais" + date) sur pages publiques ──
      function checkTopbarVisibility() {
        var topbar = document.getElementById('appTopbar');
        if (!topbar) return;
        var pagesPubliques = ['page-presentation', 'page-inscription', 'page-login', 'page-admin'];
        var pages = document.querySelectorAll('.page.active');
        var current = pages[0];
        if (!current) {
          topbar.style.display = '';
          return;
        }
        if (pagesPubliques.indexOf(current.id) > -1) {
          topbar.style.display = 'none';
        } else {
          topbar.style.display = '';
        }
      }
      // Hook showPage pour mettre à jour la topbar à chaque changement de page
      var origShowPage_v95tb = window.showPage;
      if (typeof origShowPage_v95tb === 'function') {
        window.showPage = function() {
          var r = origShowPage_v95tb.apply(this, arguments);
          setTimeout(checkTopbarVisibility, 50);
          return r;
        };
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function(){
          checkAdminUrl();
          checkTopbarVisibility();
        });
      } else {
        checkAdminUrl();
        checkTopbarVisibility();
      }
    })();


// ════════════════════════════════════════════════════════════════
// HACCP Pro V114 — Sauvegarde cloud des contrôles
// Cette fonction envoie une copie du contrôle dans Supabase.
// Si Supabase est indisponible, on ne casse rien : les données 
// restent dans le navigateur comme avant.

// ════════════════════════════════════════════════════════════════
async function enregistrerControleHACCP(nomModule, donnees) {
  // Sécurité 1 : si mode local actif ou pas d'utilisateur connecté → on s'arrête sans erreur
if (!ETAB_ID) {
    console.info('[HACCP Cloud] Mode local — contrôle non envoyé au cloud');
    return { ok: false, msg: 'Mode local' };
  }


// Préparation des données (on retire les photos pour éviter de dépasser les limites de taille)
  var contenuPropre = JSON.parse(JSON.stringify(donnees || {}));
  if (contenuPropre.photos) delete contenuPropre.photos;
  if (contenuPropre.photo)  delete contenuPropre.photo;
  var controle = {
    code_client:   String(ETAB_ID),
    module:        String(nomModule),
    contenu:       contenuPropre,
    signature:     (donnees && donnees.signature) ? String(donnees.signature) : null,
    photos:        [],
    nc_detectee:   !!(donnees && donnees.nc_detectee),
    nc_details:    (donnees && donnees.nc_details) ? String(donnees.nc_details) : null,
    date_controle: new Date().toISOString()
  };

  // Envoi via REST direct (compatible iPhone Safari — même méthode que le reste de l'appli)
  try {
    var response = await fetch(SUPABASE_URL + '/rest/v1/controles_haccp', {
      method: 'POST',
      headers: {
        'apikey':        SUPABASE_ANON,
        'Authorization': 'Bearer ' + SUPABASE_ANON,
        'Content-Type':  'application/json',
        'Prefer':        'return=minimal'
      },
      body: JSON.stringify(controle)
    });
    if (!response.ok) {
      console.error('[HACCP Cloud] Erreur ' + response.status);
      return { ok: false, msg: 'Erreur ' + response.status };
    }
    console.info('[HACCP Cloud] ✓ Contrôle "' + nomModule + '" envoyé au cloud');
    return { ok: true };
  } catch(err) {
    console.error('[HACCP Cloud] Échec envoi:', err);
    return { ok: false, msg: 'Erreur réseau' };
  }
}


// ════════════════════════════════════════════════════════════════
// HACCP Pro V114 — Espion universel cloud v3
// Surveille toutes les boîtes haccp_module_data_page-*
// et synchronise les nouveaux contrôles vers Supabase
// ════════════════════════════════════════════════════════════════
(function() {
  if (typeof localStorage === 'undefined') return;

  var snapshot = {};

  function compterEntries(cle) {
    try {
      var c = localStorage.getItem(cle);
      if (!c) return 0;
      var a = JSON.parse(c);
      return Array.isArray(a) ? a.length : 0;
    } catch(e) { return 0; }
  }

  function scanKeys() {
    var r = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf('haccp_module_data_page-') === 0) r.push(k);
    }
    return r;
  }

  // Snapshot initial
  scanKeys().forEach(function(k) { snapshot[k] = compterEntries(k); });

  var totalInitial = 0;
  for (var k in snapshot) totalInitial += snapshot[k];
  console.info('[HACCP Espion v3] ✓ Surveillance active sur ' + Object.keys(snapshot).length + ' modules (' + totalInitial + ' contrôles existants)');

  // Polling toutes les 3 secondes
  setInterval(function() {
    scanKeys().forEach(function(k) {
      var actuelle = compterEntries(k);
      var precedente = snapshot[k] || 0;
      if (actuelle > precedente) {
        try {
          var arr = JSON.parse(localStorage.getItem(k));
          var nouveaux = arr.slice(precedente);
          snapshot[k] = actuelle;

          var m = k.match(/haccp_module_data_page-([^_]+)_/);
          var moduleCourt = m ? m[1] : 'inconnu';

          nouveaux.forEach(function(entry) {
            var donnees = entry.data || entry;
            var moduleNom = (donnees && donnees.module) || moduleCourt;
            enregistrerControleHACCP(moduleNom, donnees);
          });
nouveaux.forEach(function(entry) {
            var donnees = entry.data || entry;
            var moduleNom = (donnees && donnees.module) || moduleCourt;
         
            enregistrerControleHACCP(moduleNom, donnees);
          });
          console.info('[HACCP Espion v3] ✓ ' + nouveaux.length + ' contrôle(s) "' + moduleCourt + '" envoyé(s) au cloud');
        } catch(e) { /* ignore */ }
      }
    });
  }, 3000);
})();